"use strict";

/* =========================================================
   Fälscher – Fragen (295 Stück)
   Felder: id, typ (wort, geschichte, ereignis, herkunft, natur),
   frage, antwort (offizielle Antwort, max. 200 Zeichen, bewusst in
   wechselndem Stil) und erklaerung (nur beim Aufdecken).
   Online liest nur der Server diese Datei; die offizielle Antwort
   geht erst beim Aufdecken an die Geräte.
   ========================================================= */
const FAELSCHER_FRAGEN = [
  {"id":"w-1","typ":"wort","frage":"Was ist in der Typografie ein „Zwiebelfisch“?","antwort":"Ein einzelner Buchstabe, der versehentlich in einer falschen Schriftart oder -größe im Text steht.","erklaerung":"Der Begriff stammt aus dem Bleisatz: Rutschte eine Letter in das falsche Fach des Setzkastens, landete sie später im falschen Text. Bastian Sick benannte danach seine Sprachkolumne."},
  {"id":"w-2","typ":"wort","frage":"Was ist ein „Feierabendziegel“?","antwort":"Ein verzierter Dachziegel, den Ziegler nach Feierabend für sich selbst gestaltet haben – mit Sprüchen, Namen oder Bildchen.","erklaerung":"Solche Ziegel wurden oft mit den Fingern bemalt oder eingeritzt und trugen oft auch Glücks- oder Schutzsprüche. Heute sind sie begehrte Sammlerstücke und landen in Heimatmuseen."},
  {"id":"w-3","typ":"wort","frage":"Was ist in der Seemannssprache ein „Kaventsmann“?","antwort":"Eine riesige Monsterwelle.","erklaerung":"Kaventsmann bezeichnet allgemein ein besonders großes Prachtexemplar – auf See vor allem eine Welle, die deutlich höher ist als die umgebenden Wellen."},
  {"id":"w-4","typ":"wort","frage":"Was ist ein „Hasenbrot“?","antwort":"Das Pausenbrot, das Papa abends unangetastet wieder mit heimbringt und den Kindern gibt – angeblich vom Hasen.","erklaerung":"Kinder fanden das schon etwas trockene Brot dank der Geschichte vom Hasen, der es geschickt hat, plötzlich besonders lecker. Der Brauch war vor allem in der Nachkriegszeit verbreitet."},
  {"id":"w-5","typ":"wort","frage":"Was ist „Drachenfutter“?","antwort":"Ein Geschenk, mit dem ein Mann seine verärgerte Frau besänftigen will, etwa Blumen nach dem Zuspätkommen.","erklaerung":"Der scherzhafte, recht alte Ausdruck steht so im Duden. Der „Drache“ ist dabei die zürnende Ehefrau – heute klingt das zum Glück ziemlich altbacken."},
  {"id":"w-6","typ":"wort","frage":"Was ist ein „Hackenporsche“?","antwort":"Ein Einkaufstrolley auf Rädern, den man hinter sich herzieht","erklaerung":"Der Spottname kommt daher, dass der Wagen gern gegen die Hacken (Fersen) der Leute dahinter stößt. Oft wird er mit älteren Menschen in Verbindung gebracht."},
  {"id":"w-7","typ":"wort","frage":"Was ist ein „Plümo“?","antwort":"Eine Bettdecke – genauer ein dickes Federbett.","erklaerung":"Das Wort kommt vom französischen „plumeau“ (Federbett, von „plume“ = Feder) und ist vor allem im Westen und Südwesten Deutschlands landschaftlich verbreitet."},
  {"id":"w-8","typ":"wort","frage":"Was ist „Rapunzel“, wenn man es nicht als Märchenfigur meint?","antwort":"Feldsalat – so heißt er in manchen Regionen.","erklaerung":"Im Grimm-Märchen hat die Mutter Heißhunger auf Rapunzeln aus dem Garten der Zauberin. Ob damit Feldsalat oder die Rapunzel-Glockenblume gemeint war, ist allerdings nicht sicher."},
  {"id":"w-9","typ":"wort","frage":"Was ist ein schwäbischer „Pfitzauf“?","antwort":"Ein Eierteig-Gebäck, das in speziellen Förmchen im Ofen stark aufgeht und dann innen hohl ist.","erklaerung":"Der Name kommt davon, dass der Teig beim Backen über den Förmchenrand „aufpfitzt“. Wer währenddessen die Ofentür öffnet, riskiert, dass das Ganze in sich zusammenfällt."},
  {"id":"w-10","typ":"wort","frage":"Was ist ein „Hagestolz“?","antwort":"Ein älterer, eingefleischter Junggeselle.","erklaerung":"Ursprünglich war ein „Hagestalt“ der Besitzer eines kleinen eingehegten Nebenguts. Solche nachgeborenen Söhne hatten oft nicht genug, um eine Familie zu gründen, und blieben ledig."},
  {"id":"w-11","typ":"wort","frage":"Was ist eine „Muhme“?","antwort":"Eine Tante.","erklaerung":"Ursprünglich meinte Muhme die Schwester der Mutter, später allgemein eine weibliche Verwandte. Das Gegenstück auf männlicher Seite war der „Oheim“, der Onkel."},
  {"id":"w-12","typ":"wort","frage":"Was war früher ein „Bader“?","antwort":"Der Betreiber einer Badestube, der nebenbei Haare schnitt, Zähne zog, schröpfte und Wunden versorgte.","erklaerung":"Bader waren im Mittelalter und der frühen Neuzeit die Mediziner der kleinen Leute. Ihr Beruf galt lange als „unehrlich“, also gesellschaftlich wenig angesehen."},
  {"id":"w-13","typ":"wort","frage":"Was ist ein „Stövchen“?","antwort":"Ein kleines Gestell mit einem Teelicht darin, auf das man die Teekanne zum Warmhalten stellt.","erklaerung":"Das Wort stammt aus dem Niederdeutschen und ist eng mit der ostfriesischen Teekultur verbunden. In Ostfriesland steht es bei fast jeder Teerunde auf dem Tisch."},
  {"id":"w-14","typ":"wort","frage":"Was ist ein „Ratzefummel“?","antwort":"Ein Radiergummi","erklaerung":"Der Ausdruck stammt aus der Schülersprache und ist umgangssprachlich vor allem im Norden und in Berlin verbreitet – „ratzen“ steht dabei für das Kratzen und Reiben."},
  {"id":"w-15","typ":"wort","frage":"Was bedeutet „Kladderadatsch“?","antwort":"Krach, Durcheinander oder ein großer Zusammenbruch, oft mit Skandal.","erklaerung":"Das lautmalerische Wort stammt aus dem Berlinischen. Ab 1848 hieß auch eine berühmte Berliner Satirezeitschrift so, die fast hundert Jahre lang erschien."},
  {"id":"w-16","typ":"wort","frage":"Was ist eine „Schmachtlocke“?","antwort":"Eine einzelne Haarlocke, die einem kunstvoll in die Stirn fällt","erklaerung":"Die Locke sollte romantisch-verträumt wirken, also zum Schmachten einladen. Der leicht spöttische Ausdruck steht so auch im Duden."},
  {"id":"w-17","typ":"wort","frage":"Was ist ein „Bratkartoffelverhältnis“?","antwort":"Eine Liebschaft, bei der der Mann vor allem wegen der guten Verpflegung bei der Frau bleibt.","erklaerung":"Gemeint ist eine lockere Beziehung ohne Heiratsabsicht – die Bratkartoffeln stehen für die warme Mahlzeit, die der Mann dabei bekommt."},
  {"id":"w-18","typ":"wort","frage":"Was ist die „Schafskälte“?","antwort":"Ein Kälteeinbruch Mitte Juni, wenn die Schafe meist schon geschoren sind.","erklaerung":"Die Schafskälte ist eine sogenannte meteorologische Singularität, die in Mitteleuropa recht häufig um den 11. Juni auftritt. Frisch geschorene Schafe konnten dabei frieren oder sogar erkranken."},
  {"id":"w-19","typ":"wort","frage":"Was ist ein „Drumlin“?","antwort":"Ein länglicher, stromlinienförmiger Hügel, den ein Gletscher in der Eiszeit geformt hat.","erklaerung":"Drumlins treten oft in Schwärmen auf, etwa im Alpenvorland oder in Irland. Das Wort stammt aus dem Irischen „droimnín“ für einen kleinen Rücken."},
  {"id":"w-20","typ":"wort","frage":"Was ist eine „Hallig“?","antwort":"Eine kleine Insel ohne Deich im Wattenmeer, die bei Sturmflut überspült wird.","erklaerung":"Die Häuser auf den nordfriesischen Halligen stehen auf künstlichen Hügeln, den Warften. Bei „Land unter“ ragen nur noch diese Warften aus dem Wasser."},
  {"id":"w-21","typ":"wort","frage":"Was ist ein „Kummerbund“?","antwort":"Eine breite Stoffbinde, die man zum Smoking um die Taille trägt.","erklaerung":"Mit Kummer hat das nichts zu tun: Das Wort kommt über das Englische aus dem Hindi/Persischen „kamarband“, was so viel wie Hüftband heißt."},
  {"id":"w-22","typ":"wort","frage":"Was ist ein „Vertiko“?","antwort":"Ein halbhoher Schrank mit Tür, oben einer Schublade und oft einem verzierten Aufsatz.","erklaerung":"Das Möbel war im 19. Jahrhundert, besonders in der Gründerzeit, in bürgerlichen Wohnzimmern beliebt. Auf dem Aufsatz wurden gern Nippes und Familienfotos ausgestellt."},
  {"id":"w-23","typ":"wort","frage":"Was ist ein „Fuchsschwanz“ im Werkzeugkasten?","antwort":"Eine Handsäge mit breitem Blatt, ohne Bügel.","erklaerung":"Ihren Namen hat die Säge von ihrer Form, die sich zur Spitze hin verjüngt. Sie ist vor allem zum groben Ablängen von Holz gedacht."},
  {"id":"w-24","typ":"wort","frage":"Was ist im Werkzeugkasten ein „Engländer“?","antwort":"Ein verstellbarer Schraubenschlüssel","erklaerung":"Der Spitzname geht darauf zurück, dass der verstellbare Schraubenschlüssel im 19. Jahrhundert in England entwickelt wurde. Mit einer Stellschraube passt er auf viele Mutterngrößen."},
  {"id":"w-25","typ":"wort","frage":"Was ist ein „Leporello“?","antwort":"Ein Faltbuch aus einem langen Papierstreifen, der zickzackförmig gefaltet ist – wie ein Akkordeon.","erklaerung":"Benannt ist es nach Leporello, dem Diener in Mozarts „Don Giovanni“: In der Registerarie entrollt er eine lange Liste mit den Eroberungen seines Herrn."},
  {"id":"w-26","typ":"wort","frage":"Was ist die „Unruh“?","antwort":"Das Schwungrad mit Spiralfeder in einer mechanischen Uhr, das hin- und herschwingt und so den Takt vorgibt.","erklaerung":"Die Unruh ist das Herz mechanischer Armbanduhren: Ihre gleichmäßigen Schwingungen bestimmen, wie genau die Uhr geht. Sie erfüllt dieselbe Aufgabe wie das Pendel einer Standuhr."},
  {"id":"w-27","typ":"wort","frage":"Was bedeutet „Syzygie“?","antwort":"Drei Himmelskörper stehen ungefähr auf einer Linie, zum Beispiel Sonne, Erde und Mond.","erklaerung":"Syzygien gibt es bei jedem Neumond und Vollmond, und nur dann sind Sonnen- oder Mondfinsternisse möglich. Das Wort kommt vom griechischen „syzygia“ für Verbindung, Paarung."},
  {"id":"w-28","typ":"wort","frage":"Was ist ein „Hapax legomenon“?","antwort":"Ein Wort, das in einem Text oder einer ganzen Sprache nur ein einziges Mal belegt ist.","erklaerung":"Der griechische Ausdruck bedeutet „einmal gesagt“. Für Übersetzer alter Texte wie der Bibel sind solche Wörter knifflig, weil man ihre Bedeutung nicht aus anderen Stellen erschließen kann."},
  {"id":"w-29","typ":"wort","frage":"Was war eine „Marketenderin“?","antwort":"Eine Händlerin, die mit dem Heer mitzog und den Soldaten Essen, Schnaps und Alltagsdinge verkaufte.","erklaerung":"Die berühmteste ist wohl Brechts „Mutter Courage“, die im Dreißigjährigen Krieg mit ihrem Planwagen den Truppen folgt. Heute gibt es Marketenderinnen noch bei Schützenvereinen und Trachtenkapellen."},
  {"id":"w-30","typ":"wort","frage":"Was ist im Bergbau eine „Kaue“?","antwort":"Der Umkleide- und Waschraum der Bergleute.","erklaerung":"Typisch für Kauen im Ruhrgebiet: Die Kleidung hängt an Haken, die an Ketten bis unter die Decke gezogen werden. So trocknet sie und spart Platz."},
  {"id":"w-31","typ":"wort","frage":"Was ist eine „Wechte“?","antwort":"Ein vom Wind geformter Schneeüberhang an einem Berggrat","erklaerung":"Wechten sind für Bergsteiger tückisch, weil man von oben oft nicht erkennt, wo der feste Fels endet. Brechen sie ab, können sie auch Lawinen auslösen."},
  {"id":"w-32","typ":"wort","frage":"Was ist in der Schweiz ein „Znüni“?","antwort":"Der Snack am Vormittag – so gegen neun Uhr.","erklaerung":"Das Wort heißt wörtlich „zu neun“. Das Gegenstück am Nachmittag ist das „Zvieri“, also der Imbiss um vier Uhr."},
  {"id":"w-33","typ":"wort","frage":"Was ist auf Österreichisch und Bairisch ein „Gspusi“?","antwort":"Eine Liebschaft oder Affäre – auch die Person, mit der man was am Laufen hat.","erklaerung":"Das Wort kommt vom italienischen „sposa“ (Braut) bzw. „sposo“ (Bräutigam). Gemeint ist meist eine nicht ganz ernsthafte oder heimliche Beziehung."},
  {"id":"w-34","typ":"wort","frage":"Was ist ein „Pömpel“?","antwort":"Eine Saugglocke zum Freimachen verstopfter Abflüsse und Toiletten","erklaerung":"Der Ausdruck ist vor allem in Norddeutschland und im Ruhrgebiet geläufig. Anderswo heißt dasselbe Gerät Saugglocke, Plopper oder Gummistampfer."},
  {"id":"w-35","typ":"wort","frage":"Was ist auf Sächsisch ein „Nischel“?","antwort":"Der Kopf.","erklaerung":"Das riesige Karl-Marx-Monument in Chemnitz, ein über sieben Meter hoher Bronzekopf, wird von den Einheimischen liebevoll „Nischel“ genannt."},
  {"id":"w-36","typ":"wort","frage":"Was ist auf Bairisch eine „Zwiderwurzn“?","antwort":"Ein grantiger, ewig schlecht gelaunter Mensch","erklaerung":"„Zwider“ heißt im Bairischen so viel wie zuwider, unangenehm. Eine Zwiderwurzn ist also jemand, der von Grund auf missmutig ist."},
  {"id":"w-37","typ":"wort","frage":"Was ist auf Schwäbisch „Gsälz“?","antwort":"Marmelade beziehungsweise Konfitüre","erklaerung":"Das Wort hängt mit „salzen“ zusammen, das früher allgemein „würzen, haltbar machen“ bedeutete. Ein „Gsälzbrot“ ist entsprechend ein Marmeladenbrot."},
  {"id":"w-38","typ":"wort","frage":"Was ist ein „Dubbeglas“?","antwort":"Das typische Pfälzer Schoppenglas für einen halben Liter Wein oder Schorle, mit runden Mulden außen.","erklaerung":"„Dubbe“ heißt auf Pfälzisch Tupfen. Die eingedrückten Mulden sorgen dafür, dass das Glas auch mit fettigen Fingern vom Saumagen nicht aus der Hand rutscht."},
  {"id":"w-39","typ":"wort","frage":"Was bedeutet „Schweiß“ in der Jägersprache?","antwort":"Das Blut des Wildes.","erklaerung":"Ein „Schweißhund“ ist deshalb ein Jagdhund, der die Blutspur von angeschossenem Wild verfolgt. Die Jägersprache hat für fast jedes Körperteil eigene Wörter, Augen heißen etwa „Lichter“."},
  {"id":"w-40","typ":"wort","frage":"Was ist beim Kartenspiel ein „Kiebitz“?","antwort":"Ein Zuschauer, der anderen in die Karten schaut und ungefragt Tipps gibt.","erklaerung":"Der Ausdruck wanderte über das Jiddische sogar ins Englische: Dort heißt so ein lästiger Besserwisser „kibitzer“."},
  {"id":"w-41","typ":"wort","frage":"Was ist ein „Claqueur“?","antwort":"Jemand, der dafür bezahlt wird, im Theater oder in der Oper zu klatschen und zu jubeln.","erklaerung":"Besonders in Pariser Opernhäusern des 19. Jahrhunderts gab es organisierte Claquen, die auf Bestellung Beifall spendeten oder ungeliebte Künstler auspfiffen."},
  {"id":"w-42","typ":"wort","frage":"Was ist in der Küche „Brunoise“?","antwort":"Gemüse, das in winzige Würfel von etwa 1–3 mm geschnitten ist.","erklaerung":"Brunoise gehört zu den klassischen Schnittarten der französischen Küche. Dafür schneidet man das Gemüse zuerst in feine Streifen (Julienne) und diese dann quer in Würfel."},
  {"id":"w-43","typ":"wort","frage":"Was ist in der Musik ein „Melisma“?","antwort":"Wenn man auf einer einzigen Silbe viele verschiedene Töne singt.","erklaerung":"Melismen gibt es schon im gregorianischen Choral. Heute kennt man sie vor allem von Popsängerinnen wie Whitney Houston oder Mariah Carey, die eine Silbe über viele Töne ziehen."},
  {"id":"w-44","typ":"wort","frage":"Was ist am Haus der „Ortgang“?","antwort":"Der seitliche Rand des Daches an der Giebelseite.","erklaerung":"Der Ortgang wird oft mit speziellen Ortgangziegeln oder einem Brett abgedeckt, damit kein Regen unter die Dachziegel gelangt. Die untere waagerechte Dachkante heißt dagegen Traufe."},
  {"id":"w-45","typ":"wort","frage":"Was ist eine „Plinthe“?","antwort":"Die quadratische Platte ganz unten, auf der eine Säule oder Statue steht","erklaerung":"Das Wort stammt vom griechischen „plinthos“ für Ziegelstein. Die Plinthe verteilt die Last der Säule und schützt den Säulenfuß."},
  {"id":"w-46","typ":"wort","frage":"Was ist ein „Schäkel“?","antwort":"Ein U-förmiger Metallbügel mit Schraubbolzen, um Ketten, Seile oder Lasten zu verbinden.","erklaerung":"Schäkel sind in der Seefahrt, beim Klettern und auf dem Bau unverzichtbar. Das Wort ist verwandt mit dem englischen „shackle“ für Fessel."},
  {"id":"w-47","typ":"wort","frage":"Was ist im Schach ein „Fianchetto“?","antwort":"Man zieht einen Bauern einen Schritt vor und stellt den Läufer dahinter auf die lange Diagonale.","erklaerung":"Das Wort ist Italienisch und bedeutet „kleine Flanke“. Der so entwickelte Läufer wirkt über die ganze Diagonale und schützt oft den rochierten König."},
  {"id":"w-48","typ":"wort","frage":"Was bedeutet das japanische Wort „Tsundoku“?","antwort":"Bücher kaufen und dann ungelesen stapeln","erklaerung":"Das Wort entstand im 19. Jahrhundert als Wortspiel aus „tsunde oku“ (aufstapeln und liegen lassen) und „dokusho“ (lesen). Viele Leser dürften sich ertappt fühlen."},
  {"id":"w-49","typ":"wort","frage":"Was ist „Kalsarikännit“ auf Finnisch?","antwort":"Sich allein zu Hause in Unterhose betrinken, ohne vorzuhaben, noch rauszugehen.","erklaerung":"Das Wort setzt sich aus „kalsarit“ (Unterhosen) und „kännit“ (Rausch) zusammen. Finnland nahm es sogar in eine offizielle Emoji-Sammlung zur Landeskultur auf."},
  {"id":"w-50","typ":"wort","frage":"Was bedeutet das niederländische Wort „uitwaaien“?","antwort":"Bei kräftigem Wind spazieren gehen, um den Kopf freizubekommen.","erklaerung":"Wörtlich heißt es etwa „auswehen“. Gern macht man das am Strand oder auf dem Deich – der Wind soll Sorgen und Stress einfach wegpusten."},
  {"id":"w-51","typ":"wort","frage":"Was bedeutet das portugiesische Wort „cafuné“?","antwort":"Jemandem zärtlich mit den Fingern durchs Haar streichen.","erklaerung":"Das Wort stammt aus dem brasilianischen Portugiesisch und hat Wurzeln in der afrikanischen Sprache Kimbundu. Es taucht oft in Listen „unübersetzbarer“ Wörter auf."},
  {"id":"w-52","typ":"wort","frage":"Was bedeutet das spanische Wort „Sobremesa“?","antwort":"Das gemütliche Sitzenbleiben am Tisch nach dem Essen, um zu reden.","erklaerung":"Wörtlich heißt es „über dem Tisch“. In Spanien kann die Sobremesa nach einem Mittagessen leicht länger dauern als die Mahlzeit selbst."},
  {"id":"w-53","typ":"wort","frage":"Was bedeutet das schwedische Wort „mångata“?","antwort":"Die glitzernde Spur, die der Mond nachts auf dem Wasser bildet und die aussieht wie eine Straße.","erklaerung":"Wörtlich heißt es „Mondstraße“, aus „måne“ (Mond) und „gata“ (Straße). Im Deutschen gibt es dafür kein eigenes gängiges Wort."},
  {"id":"w-54","typ":"wort","frage":"Was bedeutet das schottische Wort „tartle“?","antwort":"Kurz zögern, wenn man jemanden vorstellen soll, weil einem sein Name gerade nicht einfällt.","erklaerung":"Das Scots-Wort beschreibt allgemein das Stocken, wenn man eine Person oder Sache nicht sofort erkennt. Fast jeder kennt den peinlichen Moment."},
  {"id":"w-55","typ":"wort","frage":"Was ist ein „Mondegreen“?","antwort":"Ein verhörter Liedtext oder Satz, bei dem man etwas anderes versteht, als gesungen wird.","erklaerung":"Die Autorin Sylvia Wright hörte als Kind in einer Ballade „and Lady Mondegreen“ statt „and laid him on the green“ und prägte 1954 so den Begriff."},
  {"id":"w-56","typ":"wort","frage":"Was ist ein „Ultracrepidarian“?","antwort":"Jemand, der überall mitredet – besonders bei Dingen, von denen er keine Ahnung hat.","erklaerung":"Das englische Wort geht auf die Anekdote vom Maler Apelles zurück, der einem Schuster sagte, er solle nicht über den Schuh hinaus urteilen – unser „Schuster, bleib bei deinem Leisten“."},
  {"id":"w-57","typ":"wort","frage":"Was bedeutet das englische Wort „apricity“?","antwort":"Die Wärme der Sonne an einem kalten Wintertag.","erklaerung":"Das Wort kommt vom lateinischen „apricus“ (sonnig) und ist im Wörterbuch von Henry Cockeram von 1623 belegt. Es galt lange als ausgestorben und wird heute gern wiederentdeckt."},
  {"id":"w-58","typ":"wort","frage":"Was ist ein „Snollygoster“?","antwort":"Ein gerissener, prinzipienloser Mensch, vor allem ein Politiker, der nur auf eigenen Vorteil aus ist.","erklaerung":"Das Wort stammt aus dem Amerikanischen des 19. Jahrhunderts. Es klingt wie ein Fantasiewort, steht aber tatsächlich in großen englischen Wörterbüchern wie Merriam-Webster."},
  {"id":"w-59","typ":"wort","frage":"Was bedeutet das englische Wort „widdershins“?","antwort":"Gegen den Uhrzeigersinn bzw. gegen den Lauf der Sonne.","erklaerung":"Wer im Volksglauben widdershins um eine Kirche lief, sollte Unglück anziehen oder Feen herbeirufen. Das Wort stammt aus dem Mittelniederdeutschen „weddersinnes“."},
  {"id":"w-60","typ":"wort","frage":"Was ist ein „Borborygmus“?","antwort":"Ein Gluckern oder Knurren im Bauch, verursacht durch Gas und Flüssigkeit im Darm","erklaerung":"Das Wort kommt aus dem Griechischen und ist lautmalerisch – es soll klingen wie das Geräusch selbst. Mediziner nutzen es auch heute als Fachbegriff."},
  {"id":"g-1","typ":"geschichte","frage":"Warum mussten bärtige Männer im Russland Peters des Großen eine kleine Münze bei sich tragen?","antwort":"Als Quittung: Die Marke bewies, dass sie die Bartsteuer bezahlt hatten.","erklaerung":"Peter I. wollte Russland nach westeuropäischem Vorbild modernisieren und führte 1705 eine Steuer auf Bärte ein. Wer zahlte, bekam eine Bartmarke mit Inschrift wie „Der Bart ist eine überflüssige Last“."},
  {"id":"g-2","typ":"geschichte","frage":"Warum wurde der Eiffelturm nicht wie geplant um 1909 wieder abgerissen?","antwort":"Weil er als Antenne für Funk und Militärtelegrafie plötzlich nützlich war.","erklaerung":"Eiffel hatte nur eine Genehmigung für 20 Jahre. Um den Turm zu retten, förderte er wissenschaftliche Experimente – die Funktechnik machte ihn für das Militär unverzichtbar."},
  {"id":"g-3","typ":"geschichte","frage":"Warum gab es in Schweden im Jahr 1712 einen 30. Februar?","antwort":"Der schrittweise Wechsel zum gregorianischen Kalender wurde vermasselt, deshalb kehrte man zum julianischen zurück und brauchte einen Extratag.","erklaerung":"Ab 1700 sollten 40 Jahre lang die Schalttage entfallen. Wegen des Großen Nordischen Krieges vergaß man das 1704 und 1708. Schweden hatte so einen eigenen Kalender und gab 1712 auf."},
  {"id":"g-4","typ":"geschichte","frage":"Warum wurde das Urkilogramm in Paris 2019 als Maßstab abgeschafft?","antwort":"Seine Masse wich messbar von den offiziellen Kopien ab – niemand wusste, welches sich verändert hatte.","erklaerung":"Der Platin-Iridium-Zylinder von 1889 driftete gegenüber seinen Kopien um rund 50 Mikrogramm. Seit dem 20. Mai 2019 ist das Kilogramm über die Planck-Konstante definiert."},
  {"id":"g-5","typ":"geschichte","frage":"Warum ließ Ignaz Semmelweis 1847 Ärzte ihre Hände in Chlorkalklösung waschen?","antwort":"Die kamen direkt aus der Leichensektion und steckten Wöchnerinnen mit Kindbettfieber an.","erklaerung":"In der Wiener Klinik der Ärzte starben weit mehr Mütter als in der Station der Hebammen. Nach dem Händewaschen sank die Sterblichkeit drastisch – Kollegen verspotteten ihn trotzdem."},
  {"id":"g-6","typ":"geschichte","frage":"Warum verlassen in Haydns „Abschiedssinfonie“ die Musiker am Ende nacheinander die Bühne?","antwort":"Ein dezenter Hinweis an den Fürsten, dass die Musiker endlich nach Hause zu ihren Familien wollten.","erklaerung":"Fürst Esterházy blieb 1772 ungewöhnlich lange in seinem Sommerschloss, die Familien der Musiker durften nicht mit. Der Fürst verstand die Botschaft: Am nächsten Tag reiste der Hof ab."},
  {"id":"g-7","typ":"geschichte","frage":"Warum hing die Mona Lisa von 1911 bis 1913 nicht im Louvre?","antwort":"Ein Handwerker hatte sie geklaut.","erklaerung":"Der Italiener Vincenzo Peruggia nahm das Bild einfach unter dem Kittel mit. Er wurde erst gefasst, als er es in Florenz verkaufen wollte. Erst der Diebstahl machte das Gemälde weltberühmt."},
  {"id":"g-8","typ":"geschichte","frage":"Warum hielt am 3. September 1967 in ganz Schweden um 4:50 Uhr der gesamte Straßenverkehr an?","antwort":"Alle mussten auf die andere Straßenseite wechseln – Schweden stellte auf Rechtsverkehr um.","erklaerung":"Der „Dagen H“ (H für Högertrafik) war generalstabsmäßig geplant. Um 5 Uhr ging es auf der rechten Seite weiter. In den Tagen danach gab es sogar weniger Unfälle als sonst."},
  {"id":"g-9","typ":"geschichte","frage":"Warum führte das Deutsche Reich 1916 als eines der ersten Länder die Sommerzeit ein?","antwort":"Um im Krieg Kohle für die Beleuchtung zu sparen.","erklaerung":"Ab dem 30. April 1916 wurden die Uhren vorgestellt, Österreich-Ungarn zog mit. Andere Kriegsparteien kopierten die Idee schnell, nach dem Krieg wurde sie wieder abgeschafft."},
  {"id":"g-10","typ":"geschichte","frage":"Warum ist Canberra die Hauptstadt Australiens?","antwort":"Kompromiss: Weder Sydney noch Melbourne gönnten der jeweils anderen Stadt den Titel.","erklaerung":"Die Verfassung legte fest, dass die Hauptstadt in New South Wales liegen muss, aber mindestens 100 Meilen von Sydney entfernt. Canberra wurde dafür ab 1913 eigens neu gebaut."},
  {"id":"g-11","typ":"geschichte","frage":"Warum kam der Ingenieur Percy Spencer 1945 auf die Idee des Mikrowellenherds?","antwort":"Ein Schokoriegel in seiner Hosentasche schmolz, als er neben einem laufenden Magnetron stand.","erklaerung":"Spencer arbeitete bei Raytheon an Radargeräten. Danach testete er gezielt Popcorn und ein Ei. Das erste Gerät, der „Radarange“, war fast so groß wie ein Kühlschrank."},
  {"id":"g-12","typ":"geschichte","frage":"Warum ist der 11. März 1829 ein Wendepunkt für die Musik von Johann Sebastian Bach?","antwort":"Der 20-jährige Felix Mendelssohn führte in Berlin die Matthäus-Passion auf – zum ersten Mal seit Bachs Tod.","erklaerung":"Bach galt damals als altmodisch und war weitgehend vergessen. Die Aufführung in der Sing-Akademie war ein Riesenerfolg und löste die Bach-Renaissance aus."},
  {"id":"g-13","typ":"geschichte","frage":"Warum schrieb Maurice Ravel ein Klavierkonzert nur für die linke Hand?","antwort":"Auftragswerk für den Pianisten Paul Wittgenstein, der im Ersten Weltkrieg seinen rechten Arm verloren hatte.","erklaerung":"Wittgenstein, Bruder des Philosophen Ludwig, bestellte bei vielen Komponisten solche Werke, auch bei Prokofjew und Strauss. Ravels Konzert von 1930 ist das bekannteste davon."},
  {"id":"g-14","typ":"geschichte","frage":"Warum steht auf der Piazza della Signoria in Florenz nur eine Kopie von Michelangelos David?","antwort":"Das Original wurde 1873 vor Wind und Wetter ins Museum gerettet.","erklaerung":"Über 350 Jahre stand der Marmor-David im Freien und litt unter Regen und Verwitterung. Heute steht er in der Galleria dell'Accademia, die Kopie auf dem Platz kam 1910."},
  {"id":"g-15","typ":"geschichte","frage":"Warum bekam Albert Einstein den Nobelpreis für Physik?","antwort":"Für die Erklärung des photoelektrischen Effekts – nicht für die Relativitätstheorie.","erklaerung":"Die Relativitätstheorie war dem Komitee noch zu umstritten. Den Preis für 1921 erhielt Einstein erst 1922 nachträglich, weil 1921 zunächst niemand ausgezeichnet wurde."},
  {"id":"g-16","typ":"geschichte","frage":"Warum beeilte sich Charles Darwin 1858 plötzlich, seine Evolutionstheorie zu veröffentlichen?","antwort":"Alfred Russel Wallace schickte ihm einen Aufsatz mit fast genau derselben Idee.","erklaerung":"Darwin hatte über 20 Jahre an seiner Theorie gefeilt. Freunde ließen beide Arbeiten am 1. Juli 1858 gemeinsam vortragen. „Die Entstehung der Arten“ erschien im November 1859."},
  {"id":"g-17","typ":"geschichte","frage":"Warum suchte Johann Galle im September 1846 an einer ganz bestimmten Stelle des Himmels nach einem Planeten?","antwort":"Le Verrier hatte aus Störungen der Uranusbahn ausgerechnet, wo ein unbekannter Planet stehen muss.","erklaerung":"Galle fand Neptun an der Berliner Sternwarte noch in derselben Nacht, in der der Brief ankam – weniger als ein Grad von der berechneten Position entfernt."},
  {"id":"g-18","typ":"geschichte","frage":"Warum fuhr die erste deutsche Eisenbahn 1835 von Nürnberg nach Fürth mit einem Engländer am Steuer?","antwort":"Weil kein Deutscher eine Lok fahren konnte – der Lokführer kam einfach mit der Lok aus England mit.","erklaerung":"Die Lokomotive „Adler“ stammte aus der Werkstatt von Robert Stephenson. Lokführer William Wilson blieb in Nürnberg und verdiente mehr als der Direktor der Bahngesellschaft."},
  {"id":"g-19","typ":"geschichte","frage":"Warum entwickelte Charles Barbier eine Punktschrift, die später Louis Braille inspirierte?","antwort":"Damit Soldaten nachts Nachrichten ohne Licht ertasten konnten.","erklaerung":"Seine „Nachtschrift“ setzte sich beim Militär nicht durch. Barbier stellte sie im Pariser Blindeninstitut vor, wo der junge Braille das 12-Punkte-System zu sechs Punkten vereinfachte."},
  {"id":"g-20","typ":"geschichte","frage":"Warum setzte das britische Parlament 1714 ein Preisgeld von bis zu 20.000 Pfund aus?","antwort":"Für eine Methode, auf See den Längengrad zu bestimmen.","erklaerung":"Ohne genaue Längengrad-Bestimmung verloren sich Schiffe regelmäßig. Der Uhrmacher John Harrison löste das Problem mit präzisen Schiffsuhren, musste aber jahrzehntelang um sein Geld kämpfen."},
  {"id":"g-21","typ":"geschichte","frage":"Warum wurde der Chemiker Antoine Lavoisier 1793 im revolutionären Frankreich verhaftet?","antwort":"Er war Generalpächter, also privater Steuereintreiber für den König.","erklaerung":"Die verhassten Generalpächter wurden kollektiv angeklagt. Lavoisier, der den Sauerstoff benannte und die Massenerhaltung belegte, wurde 1794 hingerichtet."},
  {"id":"g-22","typ":"geschichte","frage":"Warum gab es in Wien ab 1784 Särge mit Klappe im Boden?","antwort":"Joseph II. wollte Holz und Kosten sparen – der Sparsarg sollte immer wieder benutzt werden.","erklaerung":"Der Tote wurde in einen Leinensack gehüllt und durch die Klappe ins Grab gelassen. Nach heftigen Protesten der Bevölkerung nahm der Kaiser die Verordnung schon nach wenigen Monaten zurück."},
  {"id":"g-23","typ":"geschichte","frage":"Warum bewilligte das britische Parlament 1858 in Rekordzeit ein riesiges Kanalisationsnetz für London?","antwort":"Die Themse stank im heißen Sommer so extrem, dass die Abgeordneten im Parlament kaum noch arbeiten konnten.","erklaerung":"Der „Große Gestank“ zwang die Politik zum Handeln. Ingenieur Joseph Bazalgette baute daraufhin ein Abwassersystem, das bis heute in Betrieb ist."},
  {"id":"g-24","typ":"geschichte","frage":"Warum wollte Wilhelm Herschel den von ihm entdeckten Planeten Uranus „Georgium Sidus“ nennen?","antwort":"Als Schmeichelei für König Georg III.","erklaerung":"„Georgs Stern“ zahlte sich aus: Der König gab Herschel eine lebenslange Pension. Außerhalb Großbritanniens setzte sich der Name nie durch, „Uranus“ wurde Mitte des 19. Jh. Standard."},
  {"id":"g-25","typ":"geschichte","frage":"Warum notierte Mozart 1784 beim Kauf eines Stars eine kleine Melodie in sein Ausgabenbuch?","antwort":"Der Vogel pfiff fast genau das Thema aus seinem neuen Klavierkonzert in G-Dur.","erklaerung":"Neben die Noten schrieb Mozart „Das war schön!“. Der Star sang das Thema mit kleinen Abweichungen. Mozart hielt den Vogel drei Jahre lang und begrub ihn feierlich im Garten."},
  {"id":"g-26","typ":"geschichte","frage":"Warum erschien Saint-Saëns' „Karneval der Tiere“ erst nach seinem Tod im Druck?","antwort":"Er hielt es für eine alberne Spielerei, die seinem Ruf als ernster Komponist schaden würde.","erklaerung":"Er verbot die Veröffentlichung zu Lebzeiten – mit Ausnahme des „Schwans“. Das Werk von 1886 erschien 1922, ein Jahr nach seinem Tod, und wurde sein populärstes."},
  {"id":"g-27","typ":"geschichte","frage":"Warum komponierte Joseph Haydn 1797 „Gott erhalte Franz den Kaiser“?","antwort":"Er hatte in London „God Save the King“ erlebt und Österreich wollte auch so eine Hymne.","erklaerung":"Die Melodie wurde Österreichs Kaiserhymne. 1841 dichtete Hoffmann von Fallersleben darauf das „Lied der Deutschen“ – heute die deutsche Nationalhymne."},
  {"id":"g-28","typ":"geschichte","frage":"Warum bekam der Maler Daniele da Volterra den Spitznamen „Il Braghettone“ (der Hosenmaler)?","antwort":"Er musste nackten Figuren in Michelangelos „Jüngstem Gericht“ Lendentücher übermalen.","erklaerung":"Nach dem Konzil von Trient galten die vielen Nackten in der Sixtinischen Kapelle als anstößig. Volterra, ein Freund Michelangelos, übernahm den Auftrag ab 1565."},
  {"id":"g-29","typ":"geschichte","frage":"Warum wird der Papst ausgerechnet von Schweizern bewacht?","antwort":"Weil Schweizer Söldner um 1500 als die besten Soldaten Europas galten und Papst Julius II. sie 1506 anheuerte.","erklaerung":"Die erste Truppe von 150 Mann traf am 22. Januar 1506 in Rom ein. Bis heute müssen Gardisten katholische Schweizer Männer sein und mindestens 1,74 m groß."},
  {"id":"g-30","typ":"geschichte","frage":"Warum stand auf dem berühmten Schriftzug in Los Angeles ursprünglich „Hollywoodland“?","antwort":"Das war Werbung für eine Wohnsiedlung.","erklaerung":"1923 aufgestellt, sollte er nur ein paar Jahre stehen bleiben. 1949 wurde er renoviert und die Silbe „land“ entfernt, damit er für den ganzen Stadtteil steht."},
  {"id":"g-31","typ":"geschichte","frage":"Warum spricht man in Brasilien Portugiesisch und im Rest Südamerikas überwiegend Spanisch?","antwort":"Wegen des Vertrags von Tordesillas 1494, der die Neue Welt per Linie zwischen Spanien und Portugal aufteilte.","erklaerung":"Die Linie lag 370 Leguas westlich der Kapverden. Die Ostspitze Südamerikas fiel damit an Portugal, das ab 1500 von dort aus Brasilien kolonisierte und weit nach Westen ausdehnte."},
  {"id":"g-32","typ":"geschichte","frage":"Warum stellten britische Eisenbahngesellschaften in den 1840er-Jahren alle Uhren auf Londoner Zeit?","antwort":"Jede Stadt hatte ihre eigene Sonnenzeit, Fahrpläne waren dadurch ein Chaos.","erklaerung":"Bristol lag etwa zehn Minuten hinter London. Die dortige Börsenuhr hat deshalb bis heute zwei Minutenzeiger: einen für Ortszeit, einen für die „Eisenbahnzeit“."},
  {"id":"g-33","typ":"geschichte","frage":"Warum vermaßen zwei französische Astronomen in den 1790ern mühsam die Strecke von Dünkirchen bis Barcelona?","antwort":"Um daraus die Länge des Meters festzulegen.","erklaerung":"Der Meter sollte der zehnmillionste Teil der Strecke vom Nordpol zum Äquator sein. Delambre und Méchain brauchten für die Messung durch das Revolutionschaos rund sieben Jahre."},
  {"id":"g-34","typ":"geschichte","frage":"Warum ließ Dmitri Mendelejew 1869 in seinem Periodensystem absichtlich Lücken?","antwort":"Er sagte voraus, dass dort noch unentdeckte Elemente hingehören – samt ihren Eigenschaften.","erklaerung":"Gallium, Scandium und Germanium wurden in den folgenden Jahren tatsächlich entdeckt und passten fast genau zu seinen Vorhersagen. Das machte sein System schlagartig anerkannt."},
  {"id":"g-35","typ":"geschichte","frage":"Warum reiste Johannes Kepler um 1620 nach Württemberg und unterbrach seine Forschung?","antwort":"Seine Mutter war als Hexe angeklagt, und er übernahm ihre Verteidigung.","erklaerung":"Katharina Kepler saß über ein Jahr in Haft, man drohte ihr mit Folter. Dank der Verteidigungsschrift ihres Sohnes wurde sie 1621 freigesprochen."},
  {"id":"g-36","typ":"geschichte","frage":"Warum heißt das britische Königshaus seit 1917 „Windsor“?","antwort":"Der alte Name Sachsen-Coburg und Gotha klang im Ersten Weltkrieg viel zu deutsch.","erklaerung":"Pikant: Deutsche Bomber, die London angriffen, hießen ausgerechnet „Gotha“. König Georg V. benannte die Familie deshalb nach dem Schloss Windsor um."},
  {"id":"g-37","typ":"geschichte","frage":"Warum verklagte Robert Schumann 1839 seinen ehemaligen Klavierlehrer Friedrich Wieck?","antwort":"Damit er dessen Tochter Clara auch ohne väterliche Zustimmung heiraten durfte.","erklaerung":"Wieck lehnte die Verbindung erbittert ab. Das Leipziger Gericht gab dem Paar 1840 recht, die Hochzeit fand einen Tag vor Claras 21. Geburtstag statt."},
  {"id":"g-38","typ":"geschichte","frage":"Warum heißt ein Krieg zwischen Großbritannien und Spanien ab 1739 „Krieg um Jenkins' Ohr“?","antwort":"Spanische Küstenwächter hatten einem britischen Kapitän namens Robert Jenkins das Ohr abgeschnitten.","erklaerung":"Der Vorfall von 1731 wurde Jahre später politisch ausgeschlachtet, als es eigentlich um Handelsrechte in der Karibik ging. Den Namen prägte erst Thomas Carlyle über hundert Jahre später."},
  {"id":"g-39","typ":"geschichte","frage":"Warum schickte Australien 1932 Soldaten mit Maschinengewehren in den Westen des Landes?","antwort":"Gegen Emus.","erklaerung":"Rund 20.000 Emus verwüsteten die Weizenfelder von Farmern. Die Vögel waren schnell und verstreuten sich, der „Emu-Krieg“ blieb weitgehend erfolglos und wurde nach wenigen Wochen abgebrochen."},
  {"id":"g-40","typ":"geschichte","frage":"Warum standen sich 1859 auf der Insel San Juan britische und US-Truppen kampfbereit gegenüber?","antwort":"Ein amerikanischer Farmer hatte ein Schwein erschossen, das einem Briten gehörte.","erklaerung":"Das Schwein fraß seine Kartoffeln. Im „Schweinekrieg“ fiel kein Schuss mehr, das Schwein blieb das einzige Opfer. 1872 sprach Kaiser Wilhelm I. als Schiedsrichter die Inseln den USA zu."},
  {"id":"g-41","typ":"geschichte","frage":"Warum gab der Schiffsarzt James Lind 1747 manchen Matrosen täglich zwei Orangen und eine Zitrone?","antwort":"Er testete systematisch, welches Mittel gegen Skorbut hilft.","erklaerung":"Er teilte zwölf kranke Seeleute in Paare auf, die jeweils etwas anderes bekamen, z. B. Essig oder Meerwasser. Nur die Zitrusfrüchte wirkten – einer der ersten kontrollierten Versuche der Medizin."},
  {"id":"g-42","typ":"geschichte","frage":"Warum stand auf dem Südturm des Kölner Doms jahrhundertelang ein mittelalterlicher Holzkran?","antwort":"Der Bau war um 1520 mangels Geld eingestellt worden, der Kran blieb einfach oben stehen.","erklaerung":"Der Kran wurde zum Wahrzeichen Kölns. Erst ab 1842 baute man mit Hilfe wiederentdeckter mittelalterlicher Pläne weiter, der Kran verschwand 1868, fertig war der Dom 1880."},
  {"id":"g-43","typ":"geschichte","frage":"Warum ließ der römische Kaiser Vespasian Urin aus öffentlichen Latrinen besteuern?","antwort":"Urin war ein Rohstoff: Gerber und Wäscher nutzten das Ammoniak darin zum Reinigen.","erklaerung":"Als sein Sohn Titus die Steuer eklig fand, hielt Vespasian ihm laut Sueton eine Münze unter die Nase – daher „Pecunia non olet“, Geld stinkt nicht."},
  {"id":"g-44","typ":"geschichte","frage":"Warum lebte Martin Luther ab 1521 als „Junker Jörg“ auf der Wartburg?","antwort":"Er war geächtet; sein Landesherr Friedrich der Weise ließ ihn zum Schutz zum Schein entführen und verstecken.","erklaerung":"Nach dem Wormser Reichstag durfte ihn jeder straflos töten. Auf der Burg ließ er sich Bart und Haare wachsen und übersetzte in rund elf Wochen das Neue Testament ins Deutsche."},
  {"id":"g-45","typ":"geschichte","frage":"Warum ergab sich der japanische Soldat Hiroo Onoda auf den Philippinen erst im Jahr 1974?","antwort":"Weil ihm niemand befohlen hatte aufzuhören – er gab erst auf, als sein ehemaliger Vorgesetzter persönlich anreiste.","erklaerung":"Onoda hielt Flugblätter über das Kriegsende für feindliche Propaganda. Ein junger Abenteurer spürte ihn auf, danach entband ihn Major Taniguchi auf der Insel Lubang offiziell von seinem Befehl."},
  {"id":"g-46","typ":"geschichte","frage":"Warum ist Leonardos „Abendmahl“ in Mailand so schlecht erhalten?","antwort":"Leonardo experimentierte und malte auf trockenen Putz statt echtes Fresko. Die Farbe blätterte schon zu seinen Lebzeiten ab.","erklaerung":"Beim Fresko wird in den nassen Putz gemalt, das ist haltbar, verlangt aber schnelles Arbeiten. Leonardo wollte sich Zeit lassen. Die letzte große Restaurierung dauerte über 20 Jahre."},
  {"id":"g-47","typ":"geschichte","frage":"Warum nahmen an der ersten Fußball-WM 1930 nur vier europäische Mannschaften teil?","antwort":"Die Schiffsreise nach Uruguay dauerte wochenlang, das wollten sich die meisten Verbände nicht antun.","erklaerung":"Nur Frankreich, Belgien, Rumänien und Jugoslawien reisten an, insgesamt spielten 13 Teams. Gastgeber Uruguay wurde Weltmeister."},
  {"id":"g-48","typ":"geschichte","frage":"Warum erfand James Naismith 1891 das Basketballspiel?","antwort":"Seine Studenten brauchten im Winter einen Sport für die Halle.","erklaerung":"Der Sportlehrer am YMCA-College in Springfield sollte eine unruhige Klasse beschäftigen. Als Körbe nagelte er zwei Pfirsichkörbe an die Galerie – der Ball musste nach jedem Treffer herausgeholt werden."},
  {"id":"g-49","typ":"geschichte","frage":"Warum erfand Elizabeth Magie 1904 den Vorläufer von Monopoly?","antwort":"Um zu zeigen, wie schädlich es ist, wenn wenige Grundbesitzer alles Land kontrollieren.","erklaerung":"Ihr „Landlord's Game“ sollte die Ideen des Ökonomen Henry George verbreiten. Ironischerweise wurde daraus ein Spiel, in dem es genau darum geht, alle anderen in den Ruin zu treiben."},
  {"id":"g-50","typ":"geschichte","frage":"Warum haben Jeans kleine Kupfernieten an den Taschen?","antwort":"Weil die Taschen bei Arbeitern ständig ausrissen.","erklaerung":"Der Schneider Jacob Davis kam auf die Idee und patentierte sie 1873 gemeinsam mit seinem Stofflieferanten Levi Strauss. Der 20. Mai 1873 gilt als Geburtstag der Blue Jeans."},
  {"id":"g-51","typ":"geschichte","frage":"Warum verdoppelte Henry Ford 1914 den Lohn seiner Fabrikarbeiter auf fünf Dollar am Tag?","antwort":"Die Fluktuation war enorm – am Fließband kündigten so viele, dass ständig neue Leute angelernt werden mussten.","erklaerung":"1913 musste Ford über das Dreifache seiner Belegschaft neu einstellen. Nach dem „Five Dollar Day“ standen Tausende Bewerber Schlange und die Kündigungen brachen ein."},
  {"id":"g-52","typ":"geschichte","frage":"Warum zog das Bauhaus 1925 von Weimar nach Dessau?","antwort":"Thüringens neue rechtskonservative Regierung kürzte die Gelder drastisch.","erklaerung":"Die Kunstschule galt dort als zu links und zu modern. Dessau holte das Bauhaus aktiv in die Stadt, Walter Gropius entwarf dafür das berühmte neue Schulgebäude."},
  {"id":"g-53","typ":"geschichte","frage":"Warum verloren 1837 sieben Professoren in Göttingen auf einen Schlag ihre Stelle?","antwort":"Sie protestierten öffentlich dagegen, dass der neue König von Hannover die Verfassung aufhob.","erklaerung":"Unter den „Göttinger Sieben“ waren die Brüder Jacob und Wilhelm Grimm. Drei wurden sogar des Landes verwiesen. In ganz Deutschland wurden sie als Helden gefeiert."},
  {"id":"g-54","typ":"geschichte","frage":"Warum ließ das Kaiserreich ab 1887 den Nord-Ostsee-Kanal bauen?","antwort":"Vor allem für die Marine: Kriegsschiffe sollten zwischen Nord- und Ostsee wechseln können, ohne um Dänemark herumzufahren.","erklaerung":"Der Weg um Skagen war lang und gefährlich. Der Kanal wurde 1895 eröffnet und hieß zunächst Kaiser-Wilhelm-Kanal. Heute ist er eine der meistbefahrenen künstlichen Wasserstraßen der Welt."},
  {"id":"g-55","typ":"geschichte","frage":"Warum gab Großbritannien die Insel Helgoland 1890 an Deutschland ab?","antwort":"Im Tausch gegen Zugeständnisse in Ostafrika, vor allem Sansibar.","erklaerung":"Im Helgoland-Sansibar-Vertrag erkannte Deutschland das britische Protektorat über Sansibar an. Kolonialfans in Deutschland fanden den Deal schlecht – „eine Hose gegen einen Knopf“."},
  {"id":"g-56","typ":"geschichte","frage":"Warum saß Johann Sebastian Bach 1717 fast einen Monat lang in Weimar in Arrest?","antwort":"Er bestand zu hartnäckig auf seiner Entlassung, weil er eine bessere Stelle in Köthen antreten wollte.","erklaerung":"Herzog Wilhelm Ernst ließ ihn wegen „Halsstarrigkeit“ festsetzen und entließ ihn danach in Ungnade. In Köthen entstanden später u. a. die Brandenburgischen Konzerte."},
  {"id":"g-57","typ":"geschichte","frage":"Warum schrieb Antonio Vivaldi so viele Werke für ein Orchester aus Mädchen?","antwort":"Er war Musiklehrer an einem venezianischen Waisenhaus für Mädchen, dem Ospedale della Pietà.","erklaerung":"Die Waisenmädchen bekamen dort eine exzellente Musikausbildung, ihre Konzerte waren eine Touristenattraktion Venedigs. Vivaldi arbeitete jahrzehntelang mit Unterbrechungen dort."},
  {"id":"g-58","typ":"geschichte","frage":"Warum schloss Ole Rømer 1676, dass Licht nicht unendlich schnell ist?","antwort":"Die Verfinsterungen des Jupitermonds Io kamen zu spät, wenn die Erde weiter vom Jupiter weg war.","erklaerung":"Die Abweichung betrug mehrere Minuten – das Licht brauchte für den längeren Weg schlicht mehr Zeit. Aus seinen Daten ließ sich erstmals eine Lichtgeschwindigkeit abschätzen."},
  {"id":"g-59","typ":"geschichte","frage":"Warum heißt Rembrandts „Nachtwache“ so, obwohl die Szene am Tag spielt?","antwort":"Der Firnis dunkelte über die Jahrhunderte stark nach – das Bild sah einfach nach Nacht aus.","erklaerung":"Der Name kam erst Ende des 18. Jahrhunderts auf. Eigentlich zeigt das Gemälde die Bürgerwehr-Kompanie von Hauptmann Frans Banninck Cocq beim Ausrücken."},
  {"id":"g-60","typ":"geschichte","frage":"Warum malte Han van Meegeren 1945 unter Aufsicht von Zeugen einen „Vermeer“?","antwort":"Um zu beweisen, dass er ein Fälscher war und kein Landesverräter.","erklaerung":"Er hatte einen angeblichen Vermeer an Hermann Göring verkauft und wurde wegen Kollaboration angeklagt. Als Fälscher erhielt er nur ein Jahr Haft – und galt vielen als Held, der Göring betrogen hatte."},
  {"id":"e-1","typ":"ereignis","frage":"Welche Hindernisse mussten Schwimmer beim olympischen Hindernisschwimmen 1900 in Paris überwinden?","antwort":"Erst über eine Stange klettern, dann über eine Reihe Boote steigen und unter einer zweiten Reihe Boote durchtauchen.","erklaerung":"Das 200-Meter-Rennen fand in der Seine statt, die Strömung half den Schwimmern. Die Disziplin gab es nur dieses eine Mal bei Olympischen Spielen; Sieger wurde der Australier Frederick Lane."},
  {"id":"e-2","typ":"ereignis","frage":"Wofür gewann Olympia-Gründer Pierre de Coubertin 1912 selbst eine olympische Goldmedaille?","antwort":"Für Literatur. Er reichte ein Gedicht ein, die „Ode an den Sport“.","erklaerung":"Von 1912 bis 1948 gab es olympische Kunstwettbewerbe in Literatur, Musik, Malerei, Bildhauerei und Architektur. Coubertin reichte sein Gedicht unter den Pseudonymen Georges Hohrod und M. Eschbach ein."},
  {"id":"e-3","typ":"ereignis","frage":"Wie endete der fünfte Satz im Wimbledon-Match zwischen John Isner und Nicolas Mahut 2010?","antwort":"70:68 für Isner","erklaerung":"Das Match dauerte über drei Tage verteilt 11 Stunden und 5 Minuten, so lange wie kein anderes Tennismatch. Die Anzeigetafel blieb bei 47:47 hängen, weil sie für so hohe Spielstände nicht programmiert war."},
  {"id":"e-4","typ":"ereignis","frage":"Warum endete ein Erstliga-Fußballspiel in Madagaskar 2002 mit 149:0?","antwort":"Die Verlierermannschaft hat aus Protest gegen den Schiedsrichter absichtlich ein Eigentor nach dem anderen geschossen.","erklaerung":"SO l'Emyrne ärgerte sich über eine Schiedsrichterentscheidung im Spiel davor, die sie den Titel gekostet hatte. Gegner AS Adema stand nur staunend daneben. Der Trainer von l'Emyrne wurde danach für drei Jahre gesperrt."},
  {"id":"e-5","typ":"ereignis","frage":"Warum schoss Barbados 1994 im Spiel gegen Grenada absichtlich ein Eigentor?","antwort":"Um in die Verlängerung zu kommen. Dort zählte ein Golden Goal doppelt, und Barbados brauchte einen Sieg mit zwei Toren Vorsprung.","erklaerung":"Nach dem Eigentor zum 2:2 versuchte Grenada in den letzten Minuten, auf beide Tore ein Tor zu schießen, und Barbados verteidigte beide. In der Verlängerung traf Barbados per Golden Goal und kam weiter."},
  {"id":"e-6","typ":"ereignis","frage":"Warum wurde der „zeitlose“ Cricket-Test zwischen Südafrika und England 1939 in Durban ohne Sieger abgebrochen?","antwort":"Die Engländer mussten ihr Schiff nach Hause erwischen.","erklaerung":"Das Spiel sollte ohne Zeitlimit laufen, bis es einen Sieger gab. Nach fast zwei Wochen fehlten England nur noch 42 Runs, doch die Mannschaft musste zum Zug nach Kapstadt, wo ihr Dampfer ablegte."},
  {"id":"e-7","typ":"ereignis","frage":"Womit spielte Astronaut Alan Shepard 1971 auf dem Mond Golf?","antwort":"Mit dem Kopf eines Sechser-Eisens, den er auf den Stiel eines Werkzeugs für Bodenproben geschraubt hatte","erklaerung":"Shepard schlug während der Apollo-14-Mission zwei Bälle. Wegen des steifen Raumanzugs konnte er nur einhändig schlagen. Den Schläger hatte er heimlich eingepackt, die NASA wusste vorher kaum davon."},
  {"id":"e-8","typ":"ereignis","frage":"Was schmuggelte Astronaut John Young 1965 an Bord der Raumkapsel Gemini 3?","antwort":"Ein Corned-Beef-Sandwich","erklaerung":"Young holte das Sandwich im Flug hervor und gab es seinem Kommandanten Gus Grissom. Weil Krümel in der Schwerelosigkeit die Technik gefährden konnten, gab es danach Ärger, sogar im US-Kongress."},
  {"id":"e-10","typ":"ereignis","frage":"Warum mussten 1962 im heutigen Tansania mehrere Schulen vorübergehend schließen?","antwort":"Wegen einer Lach-Epidemie","erklaerung":"Sie begann an einem Mädcheninternat in Kashasha: Schülerinnen bekamen Lachanfälle, die Stunden bis Tage anhielten, und es breitete sich auf Dörfer aus. Man deutet es heute als massenpsychogene Erkrankung, ausgelöst durch Stress."},
  {"id":"e-11","typ":"ereignis","frage":"Was geschah im Sommer 1518 in Straßburg?","antwort":"Dutzende Menschen tanzten tagelang auf den Straßen und konnten nicht aufhören.","erklaerung":"Die „Tanzwut“ begann mit einer einzelnen Frau, später waren es viele mehr. Die Stadtoberen ließen sogar Bühnen und Musiker aufstellen, weil sie glaubten, Weitertanzen würde helfen. Ratsprotokolle belegen das Ereignis."},
  {"id":"e-12","typ":"ereignis","frage":"Welche Trophäe nahmen Soldaten aus Modena 1325 nach ihrem Sieg über Bologna mit nach Hause?","antwort":"Einen hölzernen Eimer aus einem Brunnen","erklaerung":"Nach der Schlacht von Zappolino verfolgten die Modenesen die Bologneser bis vor deren Stadt und erbeuteten den Brunneneimer. Er ist bis heute in Modena zu sehen und inspirierte das Spottepos „La secchia rapita“ (Der geraubte Eimer)."},
  {"id":"e-14","typ":"ereignis","frage":"Warum wurde der Braunbär Wojtek im Zweiten Weltkrieg offiziell als Soldat in die polnische Armee aufgenommen?","antwort":"Tiere durften nicht mit aufs Transportschiff nach Italien, als Soldat aber schon.","erklaerung":"Polnische Soldaten hatten das Bärenjunge im Iran adoptiert. Als einfacher Soldat mit Soldbuch (später Korporal) kam er mit nach Italien, wo er der Überlieferung nach Munitionskisten schleppte. Er lebte zuletzt im Zoo von Edinburgh."},
  {"id":"e-15","typ":"ereignis","frage":"Wofür hält der US-Parkranger Roy Sullivan einen Guinness-Weltrekord?","antwort":"Siebenmal vom Blitz getroffen und jedes Mal überlebt","erklaerung":"Sullivan arbeitete im Shenandoah-Nationalpark in Virginia und wurde zwischen 1942 und 1977 getroffen. Dabei verlor er u. a. einen Zehennagel und mehrmals seine Haare, die Feuer fingen."},
  {"id":"e-16","typ":"ereignis","frage":"Was aß der Franzose Michel Lotito zwischen 1978 und 1980 Stück für Stück auf?","antwort":"Ein Kleinflugzeug, eine Cessna 150.","erklaerung":"„Monsieur Mangetout“ litt an Pica, dem Drang, Ungenießbares zu essen. Er zerlegte das Flugzeug in kleine Stücke und schluckte sie mit Wasser. Außerdem verspeiste er Fahrräder, Fernseher und Einkaufswagen."},
  {"id":"e-17","typ":"ereignis","frage":"Wie gelang es Larry Walters 1982, mit seinem Gartenstuhl auf rund 4.800 Meter Höhe zu steigen?","antwort":"Er band 45 mit Helium gefüllte Wetterballons daran fest.","erklaerung":"Er wollte eigentlich nur ein paar Dutzend Meter schweben, stieg aber in die Anflugschneise des Flughafens Los Angeles. Zum Landen schoss er mit einem Luftgewehr Ballons kaputt. Danach bekam er eine Geldstrafe der Luftfahrtbehörde."},
  {"id":"e-18","typ":"ereignis","frage":"Woran arbeitete Ingenieur Richard James 1943, als er auf die Idee für das Spielzeug Slinky kam?","antwort":"An Federn, die empfindliche Messgeräte auf Kriegsschiffen bei Seegang ruhig halten sollten","erklaerung":"Eine Feder fiel ihm vom Regal und „lief“ weiter. Seine Frau Betty fand den Namen Slinky (etwa: geschmeidig). Bei der ersten Vorführung 1945 in einem Kaufhaus in Philadelphia waren 400 Stück in 90 Minuten weg."},
  {"id":"e-19","typ":"ereignis","frage":"Wofür wurde die Knetmasse Play-Doh ursprünglich verkauft?","antwort":"Als Tapetenreiniger gegen Kohlenruß.","erklaerung":"Als Gas- und Ölheizungen die Kohleöfen ersetzten, brach der Markt weg. Eine Erzieherin merkte, dass Kinder gern mit der Masse basteln; die Firma Kutol färbte sie ein und verkaufte sie ab Mitte der 1950er als Spielzeug."},
  {"id":"e-20","typ":"ereignis","frage":"Was wollten die Erfinder der Luftpolsterfolie 1957 eigentlich herstellen?","antwort":"Eine strukturierte Tapete","erklaerung":"Alfred Fielding und Marc Chavannes verschweißten zwei Duschvorhänge mit eingeschlossenen Luftblasen. Als Tapete floppte das, auch als Gewächshausdämmung. Erst als Verpackung für IBM-Computer ab 1959/60 wurde es ein Erfolg."},
  {"id":"e-22","typ":"ereignis","frage":"Warum sollte ein Nokia-Manager 2002 in Finnland 116.000 Euro Strafe zahlen, nur weil er zu schnell gefahren war?","antwort":"Weil Bußgelder in Finnland nach dem Einkommen berechnet werden","erklaerung":"Bei Tempoverstößen rechnet Finnland in Tagessätzen, die vom Nettoeinkommen abhängen. Der Manager war mit dem Motorrad innerorts zu schnell. Ähnlich teure Strafzettel für Millionäre machen dort regelmäßig Schlagzeilen."},
  {"id":"e-23","typ":"ereignis","frage":"Was wird in Japan seit 2008 bei Erwachsenen zwischen 40 und 74 Jahren bei der jährlichen Vorsorge vorgeschrieben gemessen?","antwort":"Der Bauchumfang","erklaerung":"Das sogenannte Metabo-Gesetz setzt Grenzwerte von 85 cm für Männer und 90 cm für Frauen. Wer drüber liegt, bekommt Beratung. Unter Druck stehen vor allem Firmen und Gemeinden, denen bei verfehlten Zielen höhere Abgaben drohen."},
  {"id":"e-24","typ":"ereignis","frage":"Welches Problem gab 1992 den Ausschlag für Singapurs Kaugummi-Verbot?","antwort":"Leute klebten Kaugummi an die Türsensoren der U-Bahn, sodass die Türen nicht schlossen und Züge stehen blieben.","erklaerung":"Die neue U-Bahn MRT war erst 1987 eröffnet worden und galt als Prestigeprojekt. Seit 2004 sind Nikotin- und Zahnpflegekaugummis aus der Apotheke wieder erlaubt."},
  {"id":"e-25","typ":"ereignis","frage":"Was macht beim spanischen Fest „El Colacho“ ein als Teufel verkleideter Mann?","antwort":"Er springt über Babys, die auf Matratzen auf der Straße liegen.","erklaerung":"Das Fest im Dorf Castrillo de Murcia bei Burgos wird seit dem 17. Jahrhundert zu Fronleichnam gefeiert. Der Sprung soll die im letzten Jahr geborenen Kinder von der Erbsünde reinigen und vor Unheil schützen."},
  {"id":"e-26","typ":"ereignis","frage":"Was jagen die Teilnehmer beim jährlichen Rennen am Cooper's Hill in England den steilen Hang hinunter?","antwort":"Einen Laib Käse (Double Gloucester)","erklaerung":"Der Käse bekommt einen kleinen Vorsprung und rollt den extrem steilen Hügel bei Gloucester hinab. Kaum jemand erwischt ihn, gewonnen hat, wer zuerst unten ist. Der Preis: der Käse. Stürze und Verletzungen sind fester Teil der Tradition."},
  {"id":"e-27","typ":"ereignis","frage":"Was gewinnt der Sieger der Weltmeisterschaft im Frauentragen im finnischen Sonkajärvi?","antwort":"Das Körpergewicht der getragenen Frau in Bier","erklaerung":"Der Hindernisparcours ist gut 250 Meter lang und hat einen Wassergraben. Beliebt ist der „estnische Griff“, bei dem die Frau kopfüber auf dem Rücken des Mannes hängt. Die WM gibt es seit den 1990ern."},
  {"id":"e-28","typ":"ereignis","frage":"Wie entstand 1980 das walisische Laufrennen „Man versus Horse“?","antwort":"Aus einer Kneipendiskussion: Der Wirt hörte zwei Gäste streiten, ob Mensch oder Pferd über eine lange Strecke im Gelände schneller ist.","erklaerung":"Gordon Green, Wirt im Ort Llanwrtyd Wells, organisierte daraufhin einen Wettlauf über rund 35 km. Erst 2004 gewann zum ersten Mal ein menschlicher Läufer gegen alle Pferde."},
  {"id":"e-29","typ":"ereignis","frage":"Was ist das Ziel beim Schienbeintreten, das seit Jahrhunderten zu den „Cotswold Olimpicks“ in England gehört?","antwort":"Man hält sich an den Schultern fest, tritt dem anderen gegen die Schienbeine und versucht, ihn so zu Boden zu bringen.","erklaerung":"Die Spiele bei Chipping Campden gehen auf das Jahr 1612 zurück. Als Polsterung ist nur Stroh in der Hose erlaubt. Ein Schiedsrichter, „Stickler“ genannt, überwacht die Kämpfe."},
  {"id":"e-30","typ":"ereignis","frage":"Woher stammt die Idee für den Sport Schachboxen?","antwort":"Aus einem französischen Comic von Enki Bilal","erklaerung":"Im Comic „Äquatorkälte“ (1992) kommt die Sportart erfunden vor. Der niederländische Künstler Iepe Rubingh machte sie 2003 real: Schach- und Boxrunden wechseln sich ab, man gewinnt durch K.o. oder Schachmatt."},
  {"id":"e-31","typ":"ereignis","frage":"Was machten die japanischen Stabhochspringer Nishida und Oe nach den Olympischen Spielen 1936 mit ihren Medaillen?","antwort":"Sie zersägten Silber und Bronze und ließen jeweils eine halbe Silber- und eine halbe Bronzemedaille zusammenfügen.","erklaerung":"Beide waren gleich hoch gesprungen, verzichteten aber auf ein Stechen. Das japanische Team teilte ihnen Silber und Bronze zu. Ihre Hybridmedaillen nennt man in Japan „Medaillen der ewigen Freundschaft“."},
  {"id":"e-32","typ":"ereignis","frage":"Warum wurden die ersten vier der Tour de France 1904 nachträglich disqualifiziert?","antwort":"Betrug: Manche fuhren Teilstrecken mit dem Zug oder ließen sich von Autos ziehen.","erklaerung":"Auch Zuschauer griffen Fahrer an und streuten Nägel. Sieger wurde so der Fünftplatzierte Henri Cornet, mit 19 Jahren bis heute der jüngste Tour-Sieger. Tour-Gründer Henri Desgrange wollte die Rundfahrt danach fast abschaffen."},
  {"id":"e-33","typ":"ereignis","frage":"Wie lange brauchte der Japaner Shizo Kanakuri für den olympischen Marathon, den er 1912 in Stockholm begonnen hatte?","antwort":"Gut 54 Jahre","erklaerung":"Kanakuri brach wegen der Hitze ab, kehrte bei einer Familie ein und reiste beschämt heim, ohne sich abzumelden. In Schweden galt er als vermisst. 1967 lud ihn das schwedische Fernsehen ein, den Lauf zu beenden: 54 Jahre, 8 Monate, 6 Tage, 5:32:20 Std."},
  {"id":"e-34","typ":"ereignis","frage":"Welche Rückennummer trug der 1,09 Meter große Eddie Gaedel bei seinem einzigen Major-League-Baseballeinsatz 1951?","antwort":"1/8","erklaerung":"Teambesitzer Bill Veeck schickte ihn als Werbegag an den Schlag, weil die Strike-Zone bei ihm winzig war. Gaedel hatte Anweisung, nicht zu schlagen, bekam vier Fehlwürfe und ging zur ersten Base. Danach verbot die Liga solche Einsätze."},
  {"id":"e-35","typ":"ereignis","frage":"Warum ging einer Boeing 767 von Air Canada 1983 mitten im Flug der Treibstoff aus?","antwort":"Weil beim Betanken Pfund und Kilogramm verwechselt wurden – es war nur knapp die Hälfte im Tank.","erklaerung":"Die Piloten segelten ohne Triebwerke zu einem stillgelegten Militärflugplatz in Gimli, auf dem gerade ein Autorennen stattfand. Alle an Bord überlebten. Das Flugzeug hieß danach „Gimli Glider“ und flog noch viele Jahre."},
  {"id":"e-36","typ":"ereignis","frage":"Was geschah 1980 mit dem Lake Peigneur in Louisiana?","antwort":"Er lief leer. Eine Ölbohrung hatte ein Salzbergwerk unter dem See angebohrt, und das ganze Wasser stürzte in die Stollen.","erklaerung":"Ein Strudel zog die Bohrinsel und elf Lastkähne in die Tiefe, ein Kanal kehrte seine Fließrichtung um und bildete kurz einen Wasserfall. Alle Bergleute konnten sich retten. Danach füllte sich der See mit Salzwasser und ist heute viel tiefer."},
  {"id":"e-37","typ":"ereignis","frage":"Was passiert mit dem riesigen Stroh-Weihnachtsbock in der schwedischen Stadt Gävle besonders häufig?","antwort":"Er wird angezündet","erklaerung":"Seit 1966 wird der über zehn Meter hohe Julbock jedes Jahr aufgestellt und ist in vielen Jahren zerstört worden, meist durch Brandstiftung. Inzwischen wird er mit Brandschutzmitteln behandelt und per Webcam überwacht, und Wettbüros nehmen Wetten an."},
  {"id":"e-38","typ":"ereignis","frage":"Was löste US-Talkmaster Johnny Carson im Dezember 1973 mit einem Witz aus?","antwort":"Leere Regale: Er scherzte, das Klopapier werde knapp, und die Leute machten Hamsterkäufe.","erklaerung":"Carson bezog sich auf die Aussage eines Abgeordneten über mögliche Engpässe. Millionen Zuschauer nahmen das ernst, und durch die Panikkäufe wurde Klopapier tatsächlich wochenlang knapp."},
  {"id":"e-39","typ":"ereignis","frage":"Was zeigte die BBC am 1. April 1957 in ihrer seriösen Nachrichtensendung „Panorama“?","antwort":"Eine Spaghetti-Ernte in der Schweiz, bei der Nudeln von Bäumen gepflückt wurden","erklaerung":"In den 1950ern waren Spaghetti in Großbritannien noch exotisch. Viele Zuschauer riefen an und fragten, wie sie selbst einen Spaghettibaum ziehen könnten. Die BBC riet, einen Zweig Spaghetti in eine Dose Tomatensoße zu stecken."},
  {"id":"e-41","typ":"ereignis","frage":"Welcher berühmte Künstler wurde nach dem Diebstahl der Mona Lisa 1911 von der Polizei verhört?","antwort":"Pablo Picasso","erklaerung":"Sein Freund, der Dichter Guillaume Apollinaire, saß sogar kurz in Haft, weil ein Bekannter von ihm früher Statuen aus dem Louvre gestohlen hatte. Der wahre Dieb war ein italienischer Glaser, die Mona Lisa tauchte 1913 in Florenz wieder auf."},
  {"id":"e-42","typ":"ereignis","frage":"Wie „kämpften“ Kanada und Dänemark jahrzehntelang um die winzige Hans-Insel zwischen Kanada und Grönland?","antwort":"Mit Alkohol: Beide Seiten ließen bei Besuchen ihre Flagge und eine Flasche Whisky bzw. Schnaps für die anderen da.","erklaerung":"Der „Whiskykrieg“ begann in den 1980ern. Die Kanadier hinterließen kanadischen Whisky, die Dänen Gammel Dansk. 2022 einigten sich beide Länder, die Insel einfach zu teilen."},
  {"id":"e-43","typ":"ereignis","frage":"Was passierte 2007, als sich eine Schweizer Armeeeinheit bei einer Nachtübung verlief?","antwort":"Sie marschierte aus Versehen in Liechtenstein ein.","erklaerung":"Rund 170 Soldaten kamen bei schlechtem Wetter etwa anderthalb Kilometer weit über die Grenze, bevor sie umkehrten. In Liechtenstein, das keine eigene Armee hat, bemerkte das zunächst niemand. Die Schweiz entschuldigte sich, Liechtenstein nahm es gelassen."},
  {"id":"e-44","typ":"ereignis","frage":"Wer bekam bei der Stadtratswahl in São Paulo 1959 die meisten Stimmen?","antwort":"Ein Nashorn aus dem Zoo","erklaerung":"Studenten stellten das Nashornweibchen Cacareco aus Protest gegen korrupte Politiker auf. Es erhielt rund 100.000 Stimmen, mehr als jeder echte Kandidat, die Stimmen wurden aber für ungültig erklärt. „Cacareco“ wurde in Brasilien zum Wort für Protestwahl."},
  {"id":"e-45","typ":"ereignis","frage":"Was entwendeten vier schottische Studenten an Weihnachten 1950 aus der Westminster Abbey?","antwort":"Den Stone of Scone, den alten schottischen Krönungsstein","erklaerung":"Der Stein war 1296 von England erbeutet worden und lag unter dem Krönungsthron. Beim Diebstahl zerbrach er in zwei Teile. Im April 1951 tauchte er in Arbroath Abbey wieder auf; seit 1996 liegt er offiziell in Schottland."},
  {"id":"e-46","typ":"ereignis","frage":"Was berichtete die Zeitung „The Sun“ in New York 1835 in einer Artikelserie über den Mond?","antwort":"Ein berühmter Astronom habe mit einem Riesenteleskop geflügelte Fledermausmenschen, Einhörner und aufrecht gehende Biber auf dem Mond entdeckt.","erklaerung":"Die Geschichte wurde dem echten Astronomen John Herschel untergeschoben, der von nichts wusste. Viele Leser glaubten sie, die Auflage der Zeitung schoss nach oben. Den „Great Moon Hoax“ schrieb vermutlich der Reporter Richard Adams Locke."},
  {"id":"e-47","typ":"ereignis","frage":"Wer überlebte 1901 als erster Mensch einen Sturz über die Niagarafälle in einem Fass?","antwort":"Annie Edson Taylor, eine 63-jährige Lehrerin, an ihrem Geburtstag","erklaerung":"Sie hoffte, mit der Aktion reich zu werden, um im Alter versorgt zu sein. Zwei Tage vorher hatte sie das Fass mit ihrer Katze getestet, die ebenfalls überlebte. Reich wurde sie nicht, ihr Manager verschwand mit dem Fass."},
  {"id":"e-48","typ":"ereignis","frage":"Welcher Streit führte zur Entstehung des Guinness-Buchs der Rekorde?","antwort":"Welcher Jagdvogel in Europa am schnellsten fliegt.","erklaerung":"Sir Hugh Beaver, Chef der Guinness-Brauerei, stritt sich 1951 bei einer Jagd in Irland darüber, ob Goldregenpfeifer oder Moorschneehuhn schneller sind, und fand kein Nachschlagewerk dazu. Die Zwillinge Norris und Ross McWhirter stellten dann das erste Buch zusammen."},
  {"id":"e-49","typ":"ereignis","frage":"Wie versteckte der Chemiker George de Hevesy 1940 in Kopenhagen zwei Nobelpreismedaillen vor den Nazis?","antwort":"Er löste das Gold in Königswasser auf und stellte die Flasche einfach ins Regal.","erklaerung":"Die Medaillen gehörten den deutschen Physikern Max von Laue und James Franck; sie aus Deutschland auszuführen war verboten. Die Besatzer übersahen die Flasche. Nach dem Krieg wurde das Gold zurückgewonnen und die Nobelstiftung prägte die Medaillen neu."},
  {"id":"e-50","typ":"ereignis","frage":"Warum wurden Joseph Haydns Gebeine erst 1954 vollständig beigesetzt, obwohl er 1809 starb?","antwort":"Sein Schädel war kurz nach der Beerdigung von Anhängern der Schädellehre gestohlen worden.","erklaerung":"Die Phrenologen wollten an seinem Kopf die Ursache seiner Genialität studieren. Der Schädel landete schließlich bei der Gesellschaft der Musikfreunde in Wien und wurde erst 145 Jahre nach Haydns Tod in Eisenstadt mit dem Rest des Körpers vereint."},
  {"id":"e-51","typ":"ereignis","frage":"Wann endet die Aufführung von John Cages Orgelstück „ORGAN²/ASLSP“ in der Burchardikirche in Halberstadt?","antwort":"2640","erklaerung":"Die Aufführung begann 2001 und soll 639 Jahre dauern. Ein Ton erklingt teils jahrelang; die Klangwechsel sind Ereignisse, zu denen Hunderte Besucher kommen. Der Titel steht für „As SLow aS Possible“."},
  {"id":"e-52","typ":"ereignis","frage":"Was ging im Jahr 2000 beim Pechtropfen-Experiment an der Universität von Queensland schief?","antwort":"Die Kamera, die den achten Tropfen filmen sollte, fiel genau im entscheidenden Moment aus.","erklaerung":"Das Experiment läuft seit 1927 und zeigt, dass Pech flüssig ist: Nur etwa alle zehn Jahre fällt ein Tropfen. Ein Gewitter störte im Jahr 2000 die Technik. Es gilt als das am längsten laufende Laborexperiment der Welt."},
  {"id":"e-53","typ":"ereignis","frage":"Was tat der junge Arzt Werner Forssmann 1929 in Eberswalde an sich selbst, gegen das Verbot seines Chefs?","antwort":"Er schob sich einen Katheter durch eine Armvene bis ins Herz und ließ sich dann röntgen.","erklaerung":"Er wollte zeigen, dass ein Herzkatheter ungefährlich ist. Statt Anerkennung bekam er Spott und verlor seine Stelle. 1956 erhielt er dafür den Nobelpreis für Medizin."},
  {"id":"e-54","typ":"ereignis","frage":"Was zeigte die erste Webcam der Welt an der Universität Cambridge?","antwort":"Eine Kaffeemaschine, damit niemand umsonst zur leeren Kanne lief.","erklaerung":"Die Kamera im „Trojan Room“ lief ab 1991 im Uni-Netz und ab 1993 im World Wide Web. Als sie 2001 abgeschaltet wurde, ersteigerte Spiegel Online die Kaffeemaschine bei eBay für mehrere tausend Pfund."},
  {"id":"e-56","typ":"ereignis","frage":"Warum ging die Rattenprämie der französischen Kolonialverwaltung in Hanoi 1902 nach hinten los?","antwort":"Bezahlt wurde pro Rattenschwanz. Also schnitten die Leute nur die Schwänze ab, ließen die Ratten frei und züchteten sie sogar.","erklaerung":"Die Behörden wollten die Rattenplage in der neuen Kanalisation bekämpfen. Bald sah man Ratten ohne Schwanz durch die Stadt laufen. Ökonomen führen den Fall als Beispiel für Fehlanreize an."},
  {"id":"e-57","typ":"ereignis","frage":"Welche Aufgabe übernahm der Pavian Jack in den 1880ern an einem Bahnhof in Südafrika?","antwort":"Er bediente die Signalhebel für die Züge","erklaerung":"Sein Besitzer, ein Bahnwärter, hatte beide Beine verloren und brachte Jack die Arbeit bei. Die Eisenbahn prüfte den Affen und stellte ihn dann offiziell ein, mit Lohn und einer halben Flasche Bier pro Woche."},
  {"id":"e-58","typ":"ereignis","frage":"Was ging 1992 im Pazifik über Bord, das später Meeresforschern half, Strömungen zu verstehen?","antwort":"Fast 29.000 Badewannen-Spielzeuge: gelbe Enten, blaue Schildkröten, grüne Frösche und rote Biber","erklaerung":"Ein Container riss sich bei Sturm von einem Frachter aus Hongkong los. Ozeanograf Curtis Ebbesmeyer verfolgte über Jahre, wo die „Friendly Floatees“ an Land gespült wurden, von Alaska bis Schottland."},
  {"id":"e-59","typ":"ereignis","frage":"Warum musste die Henley-on-Todd-Regatta in Alice Springs 1993 abgesagt werden?","antwort":"Im Fluss war Wasser.","erklaerung":"Der Todd River ist fast immer trocken. Bei der Regatta laufen die Teilnehmer in Booten ohne Boden durchs sandige Flussbett. 1993 führte er ausnahmsweise Wasser, also fiel das „Bootsrennen“ aus."},
  {"id":"e-60","typ":"ereignis","frage":"Was passierte im Januar 1869 mit der ersten Verkehrsampel der Welt vor dem britischen Parlament?","antwort":"Sie ist explodiert, weil Gas ausgetreten war.","erklaerung":"Die Ampel hatte Signalarme wie bei der Eisenbahn und nachts Gaslampen in Rot und Grün. Sie wurde von Hand bedient, der zuständige Polizist wurde bei der Explosion verletzt. Danach dauerte es Jahrzehnte bis zu neuen Ampeln."},
  {"id":"h-1","typ":"herkunft","frage":"Woher hat die Funktechnik Bluetooth ihren Namen?","antwort":"Vom dänischen Wikingerkönig Harald Blauzahn, der im 10. Jahrhundert verfeindete Stämme vereinte.","erklaerung":"Der Name war 1997 als Arbeitstitel gedacht: Wie Harald Völker vereinte, sollte die Technik Geräte verbinden. Das Logo kombiniert die Runen für seine Initialen H und B."},
  {"id":"h-2","typ":"herkunft","frage":"Woher hat die Spielzeugmarke LEGO ihren Namen?","antwort":"Aus dem Dänischen: „leg godt“ heißt „spiel gut“.","erklaerung":"Der Tischler Ole Kirk Christiansen gab seiner Firma 1934 den Namen. Erst später fiel auf, dass „lego“ auf Latein zufällig auch „ich setze zusammen“ bedeuten kann."},
  {"id":"h-3","typ":"herkunft","frage":"Woher hat die Klebebandmarke tesa ihren Namen?","antwort":"Von Elsa Tesmer, einer Büroleiterin bei Beiersdorf – „Te“ aus dem Nachnamen, „sa“ aus dem Vornamen.","erklaerung":"Elsa Tesmer leitete Anfang des 20. Jahrhunderts die Schreibstube von Beiersdorf. Aus ihrem Namen wurde 1906 ein Markenname gebildet, der später zum Klebefilm wanderte."},
  {"id":"h-4","typ":"herkunft","frage":"Woher hat die Hautcreme Nivea ihren Namen?","antwort":"Vom lateinischen „niveus“ – schneeweiß.","erklaerung":"Die Creme kam 1911 von Beiersdorf auf den Markt. Der Name bezieht sich auf die strahlend weiße Farbe der Creme, die damals mit einem neuartigen Emulgator hergestellt wurde."},
  {"id":"h-5","typ":"herkunft","frage":"Woher hat der Autohersteller Audi seinen Namen?","antwort":"Es ist die lateinische Übersetzung von „Horch!“ – dem Nachnamen des Gründers August Horch.","erklaerung":"Horch hatte die Rechte an seinem Namen nach einem Streit mit seiner ersten Firma verloren. Der Sohn eines Geschäftspartners, der Latein lernte, schlug 1909 die Übersetzung vor."},
  {"id":"h-6","typ":"herkunft","frage":"Woher hat die Limonade Fanta ihren Namen?","antwort":"Von „Fantasie“","erklaerung":"Fanta entstand 1940 in Deutschland, als Coca-Cola-Sirup knapp wurde. Chef Max Keith bat seine Leute, ihre Fantasie spielen zu lassen – ein Verkäufer rief daraufhin „Fanta!“."},
  {"id":"h-7","typ":"herkunft","frage":"Woher hat das Medikament Aspirin seinen Namen?","antwort":"A für Acetyl, „spir“ von der Pflanzengattung Spiraea (Mädesüß), dazu die Endung -in.","erklaerung":"Aus dem Mädesüß wurde früher Salicylsäure gewonnen. Bayer ließ den Namen 1899 schützen; in vielen Ländern ist „Aspirin“ bis heute eine geschützte Marke."},
  {"id":"h-8","typ":"herkunft","frage":"Woher hat die Automarke Mercedes ihren Namen?","antwort":"Von der Tochter eines österreichischen Autohändlers, Mercedes Jellinek.","erklaerung":"Emil Jellinek verkaufte Daimler-Wagen an der Côte d'Azur und fuhr Rennen unter dem Pseudonym „Mercédès“. Ab 1901 hießen die Daimler-Autos nach seiner damals elfjährigen Tochter."},
  {"id":"h-9","typ":"herkunft","frage":"Woher hat die Kaffeehauskette Starbucks ihren Namen?","antwort":"Vom Steuermann im Roman „Moby Dick“.","erklaerung":"Die Gründer in Seattle wollten zuerst den Namen des Walfangschiffs „Pequod“ nehmen, fanden ihn aber unpassend. So wurde es der Erste Steuermann Starbuck; auch das Sirenen-Logo ist maritim."},
  {"id":"h-10","typ":"herkunft","frage":"Woher hat der Kamerahersteller Canon seinen Namen?","antwort":"Von Kannon, der buddhistischen Göttin der Barmherzigkeit.","erklaerung":"Die erste Prototyp-Kamera der Firma hieß 1934 „Kwanon“. Ein Jahr später wurde daraus das international besser klingende „Canon“, das auch „Maßstab“ oder „Norm“ bedeutet."},
  {"id":"h-11","typ":"herkunft","frage":"Woher hat die Eismarke Häagen-Dazs ihren Namen?","antwort":"Der Name ist frei erfunden – er sollte bloß skandinavisch klingen.","erklaerung":"Das Ehepaar Mattus gründete die Marke in der Bronx in New York. Der Name sollte an Dänemark erinnern; das Dänische kennt aber gar kein „ä“ in dieser Form."},
  {"id":"h-12","typ":"herkunft","frage":"Woher hat die Videospielfigur Pac-Man ihren Namen?","antwort":"Vom japanischen Lautwort „paku paku“ für das Auf- und Zuklappen des Mundes beim Essen.","erklaerung":"In Japan hieß das Spiel 1980 „Puck Man“. Für die USA wurde es umbenannt, weil man befürchtete, Spaßvögel würden das P an den Automaten zu einem F umkritzeln."},
  {"id":"h-13","typ":"herkunft","frage":"Woher kommt das Wort „Wiki“, etwa in Wikipedia?","antwort":"Aus dem Hawaiischen, „wiki“ heißt „schnell“. Der Erfinder hatte es von einem Flughafenbus in Honolulu.","erklaerung":"Ward Cunningham nannte 1995 seine schnell editierbare Website „WikiWikiWeb“, inspiriert vom „Wiki Wiki Shuttle“ am Flughafen Honolulu. Wikipedia ist ein Kofferwort aus Wiki und Enzyklopädie."},
  {"id":"h-14","typ":"herkunft","frage":"Woher hat unerwünschte Massen-E-Mail die Bezeichnung „Spam“?","antwort":"Von einem Monty-Python-Sketch, in dem alles mit Dosenfleisch der Marke Spam serviert wird.","erklaerung":"Im Sketch von 1970 übertönen Wikinger jedes Gespräch mit „Spam, Spam, Spam“. Frühe Internetnutzer übertrugen das auf Nachrichten, die alles andere zuschütten."},
  {"id":"h-15","typ":"herkunft","frage":"Woher hat die Suchmaschine Google ihren Namen?","antwort":"Vom Zahlwort „Googol“ – eine Eins mit hundert Nullen. Falsch geschrieben.","erklaerung":"Den Begriff Googol hatte sich der neunjährige Neffe des US-Mathematikers Edward Kasner ausgedacht. Die Gründer wollten damit die riesige Datenmenge andeuten."},
  {"id":"h-16","typ":"herkunft","frage":"Woher hat das Martinshorn von Polizei und Feuerwehr seinen Namen?","antwort":"Von der Herstellerfirma Max B. Martin, deren „Martin-Horn“ eine eingetragene Marke ist.","erklaerung":"Mit dem heiligen Martin hat es nichts zu tun. In der Straßenverkehrsordnung heißt das Gerät nüchtern „Einsatzhorn“, umgangssprachlich wird aber jedes Folgetonhorn Martinshorn genannt."},
  {"id":"h-17","typ":"herkunft","frage":"Woher hat die Wurfscheibe Frisbee ihren Namen?","antwort":"Von einer Bäckerei in Connecticut, deren leere Kuchenformen Studenten sich zuwarfen.","erklaerung":"Die Frisbie Pie Company belieferte u. a. die Gegend um Yale mit Kuchen in Blechformen. Die Spielzeugfirma Wham-O übernahm den Namen 1958 – leicht abgewandelt zu „Frisbee“."},
  {"id":"h-18","typ":"herkunft","frage":"Woher hat der Teddybär seinen Namen?","antwort":"Von US-Präsident Theodore „Teddy“ Roosevelt, der sich 1902 weigerte, einen angebundenen Bären zu erschießen.","erklaerung":"Eine Zeitungskarikatur machte die Jagdszene berühmt. Ein Ladenbesitzer in Brooklyn verkaufte daraufhin Stoffbären als „Teddy's bear“ – fast zeitgleich mit Steiffs Bären in Deutschland."},
  {"id":"h-19","typ":"herkunft","frage":"Woher hat die Elektroschockwaffe Taser ihren Namen?","antwort":"Aus einem Jugendbuch: „Thomas A. Swift's Electric Rifle“.","erklaerung":"Erfinder Jack Cover war Fan der Romanreihe um den jungen Erfinder Tom Swift. Das „A.“ fügte er selbst ein, damit sich die Abkürzung besser aussprechen ließ."},
  {"id":"h-20","typ":"herkunft","frage":"Woher hat der US-Bundesstaat Kalifornien seinen Namen?","antwort":"Aus einem spanischen Ritterroman: California war dort eine Fantasieinsel voller Gold, regiert von Amazonen.","erklaerung":"Der Roman „Las sergas de Esplandián“ von Garci Rodríguez de Montalvo erschien um 1510. Die Konquistadoren hielten die Halbinsel Baja California zunächst für eine Insel und übertrugen den Namen."},
  {"id":"h-21","typ":"herkunft","frage":"Woher hat Brasilien seinen Namen?","antwort":"Von einem Baum: dem Brasilholz, aus dem roter Farbstoff gewonnen wurde.","erklaerung":"Das Holz hieß portugiesisch „pau-brasil“, wohl wegen seiner glutroten Farbe („brasa“ = Glut). Es war im 16. Jahrhundert das wichtigste Exportgut der Kolonie."},
  {"id":"h-22","typ":"herkunft","frage":"Woher hat Venezuela seinen Namen?","antwort":"Es heißt „Klein-Venedig“.","erklaerung":"Spanische Seefahrer sahen 1499 am Maracaibo-See Pfahlbauten indigener Dörfer im Wasser. Die erinnerten sie an Venedig – daraus wurde Venezuela."},
  {"id":"h-23","typ":"herkunft","frage":"Woher hat das Land Kamerun seinen Namen?","antwort":"Von Garnelen. Portugiesische Seefahrer nannten den Fluss Wouri „Rio dos Camarões“, Fluss der Krabben.","erklaerung":"Die Portugiesen erreichten die Küste um 1472 und staunten über die Massen an Krebstieren im Fluss. Aus Camarões wurde später Kamerun, Cameroon oder Cameroun."},
  {"id":"h-24","typ":"herkunft","frage":"Woher haben die Seychellen ihren Namen?","antwort":"Von einem französischen Finanzminister namens Jean Moreau de Séchelles.","erklaerung":"Er diente unter Ludwig XV. Eine französische Expedition benannte die Inseln 1756 nach ihm – aus Séchelles wurde mit der Zeit Seychelles."},
  {"id":"h-25","typ":"herkunft","frage":"Woher hat Pakistan seinen Namen?","antwort":"Es ist ein Akronym aus Regionen: Punjab, Afghania, Kaschmir, Sindh und Belutschistan.","erklaerung":"Der Student Choudhry Rahmat Ali prägte den Namen 1933 in Cambridge. Passenderweise bedeutet „pak“ auf Urdu und Persisch auch „rein“ – Pakistan also „Land der Reinen“."},
  {"id":"h-26","typ":"herkunft","frage":"Woher hat Nigeria seinen Namen?","antwort":"Eine britische Journalistin hat ihn sich 1897 in einem Zeitungsartikel ausgedacht – nach dem Fluss Niger.","erklaerung":"Flora Shaw schrieb für die Times über Kolonialfragen und heiratete später Frederick Lugard, den ersten Generalgouverneur der Kolonie. Ihr Vorschlag setzte sich gegen sperrige Namen durch."},
  {"id":"h-27","typ":"herkunft","frage":"Woher kommt das Wort „Boykott“?","antwort":"Von Charles Boycott, einem Gutsverwalter in Irland, den 1880 die ganze Gegend ächtete.","erklaerung":"Boycott wollte Pächter vertreiben. Auf Anregung der irischen Landliga arbeitete, handelte und sprach niemand mehr mit ihm – seine Ernte mussten Soldaten bewachen. Sein Name wurde sofort zum Verb."},
  {"id":"h-28","typ":"herkunft","frage":"Woher hat die Silhouette ihren Namen?","antwort":"Vom französischen Finanzminister Étienne de Silhouette.","erklaerung":"Er war 1759 nur wenige Monate im Amt und verordnete strenge Sparmaßnahmen. „À la Silhouette“ wurde Spott für alles Billige – etwa für schlichte Schattenrisse statt teurer gemalter Porträts."},
  {"id":"h-29","typ":"herkunft","frage":"Woher hat das Metall Kobalt seinen Namen?","antwort":"Vom Kobold. Bergleute glaubten, Berggeister hätten ihnen das wertlose Erz untergeschoben.","erklaerung":"Das Erz sah silbrig aus, lieferte beim Schmelzen aber kein brauchbares Metall, sondern giftige Arsendämpfe. Erst im 18. Jahrhundert wurde Kobalt als eigenes Element erkannt."},
  {"id":"h-30","typ":"herkunft","frage":"Woher hat das chemische Element Wolfram seinen Namen?","antwort":"Vom „Wolfsschaum“ – das Erz fraß beim Schmelzen das Zinn weg wie ein Wolf die Schafe.","erklaerung":"Zinnschmelzer im Erzgebirge ärgerten sich über das Mineral Wolframit, das die Ausbeute senkte. Daher kommt auch das Elementsymbol W, obwohl es international oft Tungsten heißt."},
  {"id":"h-31","typ":"herkunft","frage":"Woher hat das Edelmetall Platin seinen Namen?","antwort":"Aus dem Spanischen: „platina“ heißt „kleines Silber“ – abwertend gemeint.","erklaerung":"Spanische Goldsucher in Südamerika hielten die Körnchen für eine lästige Verunreinigung im Gold, weil sie sich kaum schmelzen ließen. Teils wurden sie einfach wieder in Flüsse gekippt."},
  {"id":"h-32","typ":"herkunft","frage":"Woher haben die Salmonellen ihren Namen?","antwort":"Von einem US-Tierarzt namens Daniel Elmer Salmon – nicht vom Lachs.","erklaerung":"Salmon leitete ein Forschungsprogramm des US-Landwirtschaftsministeriums. Den Erreger entdeckte 1885 eigentlich sein Assistent Theobald Smith, benannt wurde er aber nach dem Chef."},
  {"id":"h-33","typ":"herkunft","frage":"Woher hat der Zwergplanet Pluto seinen Namen?","antwort":"Eine elfjährige Schülerin aus Oxford hat ihn vorgeschlagen, nach dem römischen Gott der Unterwelt.","erklaerung":"Venetia Burney erzählte ihrem Großvater 1930 beim Frühstück von der Idee, der gab sie an einen Astronomen weiter. Das Lowell-Observatorium stimmte zu, sie bekam fünf Pfund Belohnung."},
  {"id":"h-34","typ":"herkunft","frage":"Woher haben die Elementarteilchen namens Quarks ihren Namen?","antwort":"Aus einer Zeile in James Joyce' Roman „Finnegans Wake“: „Three quarks for Muster Mark!“","erklaerung":"Physiker Murray Gell-Mann hatte zuerst nur einen Laut wie „kwork“ im Kopf. Bei Joyce fand er das passende Wort – praktisch, denn damals ging man von genau drei Quarks aus."},
  {"id":"h-35","typ":"herkunft","frage":"Woher hat das Wort „Vitamin“ seinen Ursprung?","antwort":"Von „vital“ und „Amin“ – man dachte, es seien lebenswichtige Stickstoffverbindungen.","erklaerung":"Der Biochemiker Casimir Funk prägte 1912 den Begriff „Vitamine“. Später stellte sich heraus, dass die meisten Vitamine gar keine Amine sind – der Name blieb trotzdem."},
  {"id":"h-36","typ":"herkunft","frage":"Woher kommt das Wort „Roboter“?","antwort":"Aus einem tschechischen Theaterstück von 1920; „robota“ bedeutet Fronarbeit.","erklaerung":"Karel Čapek schrieb das Stück „R.U.R.“ über künstliche Arbeiter. Das Wort schlug ihm sein Bruder Josef vor, nachdem Karel zunächst „Labori“ erwogen hatte."},
  {"id":"h-37","typ":"herkunft","frage":"Woher hat das Känguru seinen Namen?","antwort":"Aus der Aborigine-Sprache Guugu Yimithirr, dort hieß eine Känguruart „gangurru“.","erklaerung":"James Cooks Expedition notierte das Wort 1770 in Nordost-Australien. Die beliebte Geschichte, es bedeute „Ich verstehe dich nicht“, ist eine Legende."},
  {"id":"h-38","typ":"herkunft","frage":"Woher hat die Kiwi-Frucht ihren Namen?","antwort":"Vom neuseeländischen Nationalvogel. Exporteure tauften die „chinesische Stachelbeere“ 1959 um.","erklaerung":"Die Frucht stammt ursprünglich aus China. Für den Export in die USA suchte eine neuseeländische Firma einen griffigeren Namen – die braune, haarige Schale erinnerte an den Vogel."},
  {"id":"h-39","typ":"herkunft","frage":"Woher hat die Vanille ihren Namen?","antwort":"Vom spanischen „vainilla“, kleine Hülse – über das lateinische „vagina“, also Scheide.","erklaerung":"Gemeint ist die schotenartige Kapselfrucht der Vanille-Orchidee. Spanische Eroberer brachten das Gewürz aus Mexiko, wo es die Azteken zum Aromatisieren von Kakao nutzten."},
  {"id":"h-40","typ":"herkunft","frage":"Woher hat die Kartoffel ihren Namen?","antwort":"Vom italienischen Wort für Trüffel, „tartufolo“.","erklaerung":"Die Knollen aus der Erde erinnerten Italiener an Trüffel. Im Deutschen wurde aus „Tartuffel“ allmählich „Kartoffel“, weil sich zwei t-Laute schlecht sprechen ließen."},
  {"id":"h-41","typ":"herkunft","frage":"Woher hat das Gericht Carpaccio seinen Namen?","antwort":"Von dem venezianischen Renaissance-Maler Vittore Carpaccio, der gern kräftige Rottöne verwendete.","erklaerung":"Giuseppe Cipriani erfand 1950 in Harry's Bar in Venedig rohe Rindfleischscheiben für eine Gräfin, der ihr Arzt gekochtes Fleisch verboten hatte. In Venedig lief gerade eine Carpaccio-Ausstellung."},
  {"id":"h-42","typ":"herkunft","frage":"Woher hat der Cappuccino seinen Namen?","antwort":"Von den Kapuzinermönchen und der Farbe ihrer braunen Kutten.","erklaerung":"„Cappuccio“ ist italienisch für Kapuze, daher der Ordensname. Schon im Wien des 18. Jahrhunderts hieß Kaffee mit etwas Sahne „Kapuziner“."},
  {"id":"h-43","typ":"herkunft","frage":"Woher hat die Bratwurst ihren Namen?","antwort":"Vom althochdeutschen „brāt“ für feingehacktes Fleisch, nicht vom Braten.","erklaerung":"„Brät“ bezeichnet bis heute die Wurstmasse. Ursprünglich konnte eine Bratwurst also auch gekocht werden – erst später verband man den Namen mit dem Grill."},
  {"id":"h-44","typ":"herkunft","frage":"Woher hat die Hängematte ihren Namen?","antwort":"Aus der Sprache der Taíno in der Karibik: „hamaca“. Das wurde im Deutschen zu „Hängematte“ umgedeutet.","erklaerung":"Über das Spanische und Niederländische (hangmat) kam das Wort zu uns. Weil „Hamaca“ nichts bedeutete, formte man es zu etwas Verständlichem um – ein klassischer Fall von Volksetymologie."},
  {"id":"h-45","typ":"herkunft","frage":"Woher kommt das Wort „Shampoo“?","antwort":"Aus dem Hindi, von „chāmpo“ – massier!","erklaerung":"Gemeint war ursprünglich eine Kopf- und Körpermassage. Der indische Unternehmer Sake Dean Mahomed machte „shampooing“ Anfang des 19. Jahrhunderts mit einem Badehaus in Brighton bekannt."},
  {"id":"h-46","typ":"herkunft","frage":"Woher kommt das Wort „Emoji“?","antwort":"Aus dem Japanischen: e = Bild, moji = Schriftzeichen. Mit „Emotion“ hat es nichts zu tun.","erklaerung":"Die ersten 176 Emojis entwarf Shigetaka Kurita 1999 für einen japanischen Mobilfunkanbieter. Die Ähnlichkeit zu „Emoticon“ ist reiner Zufall."},
  {"id":"h-47","typ":"herkunft","frage":"Woher kommt das Wort „Karaoke“?","antwort":"Japanisch für „leeres Orchester“.","erklaerung":"„Kara“ heißt leer, „oke“ ist kurz für ōkesutora, Orchester. Gemeint ist Musik, bei der die Gesangsstimme fehlt – die liefert man selbst."},
  {"id":"h-48","typ":"herkunft","frage":"Woher hat die Krawatte ihren Namen?","antwort":"Von kroatischen Söldnern im 17. Jahrhundert, die ein auffälliges Halstuch trugen.","erklaerung":"Die Kroaten dienten im Dreißigjährigen Krieg auch in französischen Diensten. Aus „Hrvat“ bzw. „Croate“ wurde in Paris „cravate“ – und die Mode verbreitete sich in ganz Europa."},
  {"id":"h-49","typ":"herkunft","frage":"Woher hat Badminton seinen Namen?","antwort":"Von Badminton House, dem Landsitz des Herzogs von Beaufort in England.","erklaerung":"Britische Offiziere hatten in Indien ein Federballspiel namens „Poona“ kennengelernt. In den 1870er-Jahren wurde es auf dem Anwesen des Herzogs populär und bekam dessen Namen."},
  {"id":"h-50","typ":"herkunft","frage":"Woher hat Snooker seinen Namen?","antwort":"Es war ein Spottwort für Offiziersanwärter im ersten Ausbildungsjahr.","erklaerung":"Der britische Offizier Neville Chamberlain soll 1875 in Indien einen Mitspieler, der schlecht stieß, als „snooker“ verspottet haben. Später nannte man das ganze Spiel so."},
  {"id":"h-51","typ":"herkunft","frage":"Woher kommt das Wort „kaputt“?","antwort":"Aus einem französischen Kartenspiel: Wer beim Piquet keinen Stich machte, war „capot“.","erklaerung":"Das Wort kam im 17. Jahrhundert ins Deutsche, damals hieß es noch „caput machen“. Mit dem lateinischen „caput“ (Kopf) ist es nur entfernt verwandt."},
  {"id":"h-52","typ":"herkunft","frage":"Woher kommt der Ausdruck „08/15“ für etwas Gewöhnliches?","antwort":"Vom Maschinengewehr MG 08/15 aus dem Ersten Weltkrieg.","erklaerung":"Das Modell von 1908 wurde 1915 überarbeitet. Soldaten mussten es endlos und stumpf auseinander- und zusammenbauen – der Name wurde zum Inbegriff von Routine ohne Originalität."},
  {"id":"h-53","typ":"herkunft","frage":"Woher kommt das Wort „Torschlusspanik“?","antwort":"Aus dem Mittelalter: Abends wurden die Stadttore geschlossen, und wer zu spät kam, blieb draußen.","erklaerung":"Draußen vor der Mauer drohten Räuber, Kälte und wilde Tiere. Die Angst, es nicht mehr rechtzeitig zu schaffen, wurde später auf alle möglichen Lebensentscheidungen übertragen."},
  {"id":"h-54","typ":"herkunft","frage":"Woher kommt das Wort „Kohldampf“ für großen Hunger?","antwort":"Aus der Gaunersprache: „Kohl“ und „Dampf“ bedeuteten dort beide schon Hunger.","erklaerung":"Im Rotwelsch, der Sprache der Landstreicher, gab es mehrere Wörter für Hunger. Die Verdopplung verstärkt nur – mit Kohlgemüse oder Kochdampf hat das Wort nichts zu tun."},
  {"id":"h-55","typ":"herkunft","frage":"Woher kommt der Ausdruck „mit Kind und Kegel“?","antwort":"„Kegel“ war ein altes Wort für ein uneheliches Kind.","erklaerung":"Wer mit Kind und Kegel kam, brachte also die ganze Familie mit – eheliche wie uneheliche Kinder. Mit dem Kegelspiel hat die Redewendung nichts zu tun."},
  {"id":"h-56","typ":"herkunft","frage":"Woher kommt der Ausdruck „Schmiere stehen“?","antwort":"Aus dem Hebräischen: „schmira“ bedeutet Bewachung.","erklaerung":"Das Wort gelangte über das Jiddische in die Gaunersprache. Wer bei einem Einbruch Schmiere stand, hielt Wache – mit Fett oder Schmiermittel hat das nichts zu tun."},
  {"id":"h-57","typ":"herkunft","frage":"Woher hat der Dollar seinen Namen?","antwort":"Von einer Silbermünze aus dem böhmischen Joachimsthal, dem Joachimsthaler.","erklaerung":"Ab 1520 wurden dort Silbermünzen geprägt, kurz „Taler“ genannt. Über das niederländische „daler“ wanderte der Name nach Amerika – heute heißt der Ort Jáchymov und liegt in Tschechien."},
  {"id":"h-58","typ":"herkunft","frage":"Woher hat die Sinusfunktion ihren Namen?","antwort":"Durch einen Übersetzungsfehler: Ein arabisches Wort für Bogensehne wurde als „Busen/Bucht“ gelesen und ins Lateinische übertragen.","erklaerung":"Das Sanskrit-Wort „jya“ (Sehne) wurde arabisch „jiba“, ohne Vokale geschrieben „jb“. Man las es als „jaib“ (Busenfalte), was Gerhard von Cremona im 12. Jahrhundert mit lateinisch „sinus“ übersetzte."},
  {"id":"h-59","typ":"herkunft","frage":"Woher hat der Pudel seinen Namen?","antwort":"Von „pudeln“, also im Wasser herumplanschen. Es war ursprünglich ein Wasserhund für die Entenjagd.","erklaerung":"Pudel apportierten früher geschossene Wasservögel aus Teichen und Flüssen. Erst später wurden sie zu Mode- und Schoßhunden; in Frankreich heißen sie trotzdem bis heute „caniche“, Entenhund."},
  {"id":"h-60","typ":"herkunft","frage":"Woher kommt das Wort „Hurrikan“?","antwort":"Aus der Sprache der Taíno in der Karibik, deren Wort für einen gewaltigen Sturm die Spanier übernahmen.","erklaerung":"Spanische Seefahrer lernten die Wirbelstürme in der Karibik kennen und übernahmen das Wort als „huracán“. Im Pazifik heißen dieselben Stürme Taifun, im Indischen Ozean Zyklon."},
  {"id":"n-1","typ":"natur","frage":"Wozu haben Seeotter unter den Vorderbeinen eine lose Hautfalte?","antwort":"Als Tasche: Darin bunkern sie beim Tauchen Futter und ihren Lieblingsstein zum Muschelknacken.","erklaerung":"Seeotter gehören zu den wenigen Säugetieren, die Werkzeuge benutzen. Sie legen sich einen Stein auf die Brust und schlagen Muscheln und Seeigel darauf auf – oft behalten sie denselben Stein über längere Zeit."},
  {"id":"n-2","typ":"natur","frage":"Wie atmet die australische Fitzroy-Schildkröte, wenn sie stundenlang unter Wasser bleibt?","antwort":"Über den Hintern.","erklaerung":"Rheodytes leukops hat in der Kloake stark durchblutete Taschen (Bursae), durch die sie Sauerstoff aus dem Wasser aufnimmt. So kann sie tagelang abgetaucht bleiben, ohne an die Oberfläche zu kommen."},
  {"id":"n-3","typ":"natur","frage":"Was ist an den Fingerabdrücken von Koalas so besonders?","antwort":"Sie sehen menschlichen Fingerabdrücken zum Verwechseln ähnlich, sogar unter dem Mikroskop.","erklaerung":"Die Papillarleisten haben sich bei Koalas unabhängig vom Menschen entwickelt – vermutlich, um Eukalyptusblätter und Äste besser zu greifen. Forscher warnten scherzhaft, sie könnten Tatorte verwirren."},
  {"id":"n-4","typ":"natur","frage":"Wie betäubt der Knallkrebs seine Beute?","antwort":"Er klappt seine Schere so schnell zu, dass eine Kavitationsblase entsteht. Deren Implosion knallt lauter als ein Gewehrschuss und betäubt kleine Fische.","erklaerung":"Beim Kollaps der Blase entstehen für einen Sekundenbruchteil Temperaturen von mehreren tausend Grad und sogar ein schwaches Lichtblitzen. Kolonien von Knallkrebsen können U-Boot-Sonar stören."},
  {"id":"n-5","typ":"natur","frage":"Wie verteidigt sich der Bombardierkäfer gegen Angreifer?","antwort":"Er schießt eine fast 100 Grad heiße, ätzende Flüssigkeit aus seinem Hinterleib.","erklaerung":"Im Hinterleib mischt der Käfer Hydrochinon und Wasserstoffperoxid mit Enzymen. Die Reaktion erhitzt die Mischung explosionsartig – und er kann die Düse sogar gezielt in verschiedene Richtungen drehen."},
  {"id":"n-6","typ":"natur","frage":"Was macht die Texas-Krötenechse, wenn ein Kojote sie packen will?","antwort":"Sie spritzt ihm Blut aus den Augen entgegen.","erklaerung":"Durch erhöhten Druck platzen kleine Gefäße an den Augenlidern, der Strahl reicht über einen Meter. Das Blut schmeckt für Hunde und Kojoten offenbar so widerlich, dass sie die Echse fallen lassen."},
  {"id":"n-7","typ":"natur","frage":"Wo wohnt der Perlfisch (Carapus)?","antwort":"Im After von Seegurken.","erklaerung":"Der schlanke Fisch schlüpft rückwärts, mit dem Schwanz zuerst, in die Seegurke und versteckt sich dort tagsüber. Manche Arten fressen dabei sogar Teile der inneren Organe ihres Wirts."},
  {"id":"n-8","typ":"natur","frage":"Was haben junge Hoatzins aus Südamerika, das erwachsene Vögel nicht mehr haben?","antwort":"Krallen an den Flügeln, mit denen sie durchs Geäst klettern.","erklaerung":"Bei Gefahr lassen sich die Küken ins Wasser fallen, tauchen davon und klettern danach mit Flügelkrallen und Füßen zurück ins Nest. Mit dem Erwachsenwerden verschwinden die Krallen."},
  {"id":"n-9","typ":"natur","frage":"Was macht die Qualle Turritopsis dohrnii, wenn sie verletzt wird oder hungert?","antwort":"Sie verjüngt sich: Sie wird wieder zum Polypen und startet ihr Leben von vorn.","erklaerung":"Ihre Zellen können sich in andere Zelltypen zurückverwandeln (Transdifferenzierung). Deshalb wird sie oft „unsterbliche Qualle“ genannt – gefressen werden oder an Krankheiten sterben kann sie natürlich trotzdem."},
  {"id":"n-10","typ":"natur","frage":"Wie überstehen Kolibris kalte Nächte, ohne zu verhungern?","antwort":"Sie fallen in Torpor, eine Art Mini-Winterschlaf für eine Nacht.","erklaerung":"Ihr Stoffwechsel ist tagsüber so schnell, dass die Energie für die Nacht nicht reichen würde. Im Torpor sinken Herzschlag und Körpertemperatur drastisch – bei Andenkolibris auf unter 5 °C."},
  {"id":"n-11","typ":"natur","frage":"Wo liegt die Zunge eines Spechts, wenn er sie gerade nicht herausstreckt?","antwort":"Um den Schädel gewickelt – vom Unterkiefer über den Hinterkopf bis nach vorne zur Stirn.","erklaerung":"Das Zungenbein ist bei Spechten extrem verlängert und läuft in einer Schlaufe um den Schädel. So kann die Zunge weit in Bohrlöcher geschoben werden, um Larven herauszuholen."},
  {"id":"n-12","typ":"natur","frage":"Wie überlebt der Nacktmull bis zu 18 Minuten ganz ohne Sauerstoff?","antwort":"Er stellt seinen Stoffwechsel auf Fruchtzucker um.","erklaerung":"Bei Sauerstoffmangel verbrennt der Nacktmull Fruktose statt Glukose – ein Weg, der ohne Sauerstoff Energie liefert. Das entdeckten Forscher 2017. In ihren engen, überfüllten Bauen ist die Luft oft extrem sauerstoffarm."},
  {"id":"n-13","typ":"natur","frage":"Wie überwintert der nordamerikanische Waldfrosch?","antwort":"Er friert ein. Herz und Atmung stehen still, im Frühling taut er auf und hüpft weiter.","erklaerung":"Bis zu zwei Drittel seines Körperwassers werden zu Eis. Die Leber flutet die Zellen mit Glukose, die wie ein Frostschutzmittel wirkt und verhindert, dass Eiskristalle die Zellen zerstören."},
  {"id":"n-14","typ":"natur","frage":"Was imitiert der australische Leierschwanz außer anderen Vögeln?","antwort":"Kettensägen, Kameraauslöser, Autoalarme","erklaerung":"Leierschwanz-Männchen bauen fremde Geräusche in ihren Balzgesang ein. Vögel, die nahe an Menschen leben, haben dabei auch technische Geräusche gelernt – berühmt wurde das durch eine Doku von David Attenborough."},
  {"id":"n-15","typ":"natur","frage":"Wie findet das Schnabeltier unter Wasser seine Beute, obwohl es Augen, Ohren und Nase schließt?","antwort":"Mit Elektrorezeptoren im Schnabel, die die winzigen Muskelströme von Krebsen und Larven spüren.","erklaerung":"Im Schnabel sitzen rund 40.000 Elektrorezeptoren. Damit gehört das Schnabeltier zu den ganz wenigen Säugetieren mit Elektrosinn – beim Tauchen schwenkt es den Kopf hin und her wie einen Metalldetektor."},
  {"id":"n-16","typ":"natur","frage":"Warum schimmert das Fell von Faultieren oft grünlich?","antwort":"Weil darin Algen wachsen.","erklaerung":"Die Haare haben Rillen, in denen sich spezielle Algen ansiedeln. Das tarnt das Faultier im Blätterdach. Im Fell leben außerdem Motten, deren Ausscheidungen die Algen düngen."},
  {"id":"n-17","typ":"natur","frage":"Woran orientieren sich manche afrikanische Mistkäfer, um nachts ihre Kugel geradeaus zu rollen?","antwort":"An der Milchstraße.","erklaerung":"Forscher setzten den Käfern im Planetarium winzige Kappen auf und veränderten den Sternenhimmel. Ohne Sicht auf das Lichtband der Milchstraße liefen sie im Zickzack – es war der erste Nachweis dieser Navigation bei Tieren."},
  {"id":"n-18","typ":"natur","frage":"Wie wehrt sich der Schleimaal, wenn ein Hai ihn ins Maul nimmt?","antwort":"Er sondert blitzschnell eine riesige Menge Schleim ab, die dem Hai die Kiemen verstopft.","erklaerung":"Wenige Gramm Sekret quellen mit Meerwasser zu Litern zähem Schleim auf. Unterwasservideos zeigen, wie Haie würgend wieder loslassen. Sich selbst befreit der Aal danach, indem er einen Knoten durch seinen Körper rutschen lässt."},
  {"id":"n-19","typ":"natur","frage":"Wozu zeichnen männliche Kugelfische vor Japan große Kreismuster in den Meeresboden?","antwort":"Um Weibchen zu beeindrucken – in der Mitte legen die dann ihre Eier ab.","erklaerung":"Das etwa zwei Meter breite, symmetrische Muster schaufelt das Männchen tagelang mit den Flossen. Lange rätselten Taucher, wer diese „Unterwasser-Kornkreise“ macht, bis man 2011 den Fisch dabei filmte."},
  {"id":"n-20","typ":"natur","frage":"Wie verhindert die Venusfliegenfalle, dass sie bei jedem Regentropfen zuschnappt?","antwort":"Sie zählt: Erst wenn zwei Fühlhaare innerhalb von etwa 20 Sekunden berührt werden, klappt sie zu.","erklaerung":"Jede Berührung erzeugt ein elektrisches Signal. Nach etwa fünf Signalen beginnt die Falle, Verdauungsenzyme auszuschütten – zappelnde Beute löst also selbst die Verdauung aus."},
  {"id":"n-21","typ":"natur","frage":"Wie verbreitet die Spritzgurke ihre Samen?","antwort":"Reife Frucht platzt vom Stiel ab und schießt die Samen mitsamt Schleim mehrere Meter weit raus.","erklaerung":"In der Frucht baut sich hoher Flüssigkeitsdruck auf. Beim Ablösen wirkt das Loch am Stielansatz wie eine Düse. Die Pflanze wächst wild im Mittelmeerraum und ist giftig."},
  {"id":"n-22","typ":"natur","frage":"Wohin schauen ausgewachsene, blühende Sonnenblumen?","antwort":"Nach Osten, und zwar dauerhaft.","erklaerung":"Nur junge Pflanzen folgen der Sonne. Blühende Köpfe bleiben nach Osten gerichtet: Sie werden morgens schneller warm und locken so mehr Bienen an – das zeigte eine Studie 2016."},
  {"id":"n-23","typ":"natur","frage":"Was ist an den Blättern der Welwitschia aus der Namib-Wüste so ungewöhnlich?","antwort":"Sie hat ihr ganzes Leben lang nur zwei Blätter, die ununterbrochen weiterwachsen – teils über 1000 Jahre.","erklaerung":"Die Blätter wachsen an der Basis nach und reißen mit der Zeit in viele Streifen auf, sodass die Pflanze wie ein zerzauster Haufen aussieht. Feuchtigkeit holt sie sich zum Teil aus dem Küstennebel."},
  {"id":"n-24","typ":"natur","frage":"Was passiert, wenn bei vielen Bambusarten die Pflanzen endlich blühen?","antwort":"Alle Pflanzen der Art blühen fast gleichzeitig, oft weltweit – und sterben danach ab.","erklaerung":"Manche Arten blühen nur alle 60 bis 120 Jahre. Die plötzliche Masse an Samen lässt in Teilen Asiens Rattenpopulationen explodieren, was früher Hungersnöte auslöste."},
  {"id":"n-25","typ":"natur","frage":"Wie lockt die Ragwurz-Orchidee ihre Bestäuber an?","antwort":"Ihre Blüte imitiert ein Insektenweibchen in Form, Behaarung und Duft. Männchen versuchen sich mit ihr zu paaren und nehmen dabei Pollen mit.","erklaerung":"Biologen nennen das Sexualtäuschung. Die Blüte bietet keinerlei Nektar – die Männchen fallen nur auf den nachgeahmten Sexuallockstoff herein. Ragwurz-Arten wachsen auch in Deutschland."},
  {"id":"n-26","typ":"natur","frage":"Was ist „Pando“ im US-Bundesstaat Utah?","antwort":"Ein Espenwald aus rund 47.000 Stämmen, der genetisch ein einziges Lebewesen ist.","erklaerung":"Alle Bäume wachsen aus einem gemeinsamen Wurzelsystem und sind Klone desselben Individuums. Mit geschätzt über 6.000 Tonnen gilt Pando als einer der schwersten Organismen der Erde."},
  {"id":"n-27","typ":"natur","frage":"Warum schmeckt Orangensaft direkt nach dem Zähneputzen so bitter?","antwort":"Wegen Natriumlaurylsulfat in der Zahnpasta: Es dämpft den Süßgeschmack und verstärkt das Bittere.","erklaerung":"Der Schaumbildner blockiert vorübergehend Süß-Rezeptoren und löst zugleich Fettstoffe auf, die normalerweise die Bitterwahrnehmung bremsen. Zahnpasta ohne diesen Stoff hat den Effekt kaum."},
  {"id":"n-28","typ":"natur","frage":"Was ist der „Nasenzyklus“?","antwort":"Die Nasenlöcher wechseln sich alle paar Stunden ab, welches gerade besser Luft bekommt.","erklaerung":"Schwellkörper in der Nasenschleimhaut schwellen abwechselnd an und ab, gesteuert vom vegetativen Nervensystem. Meist merkt man es nicht – erst bei Schnupfen fällt auf, dass immer eine Seite dichter ist."},
  {"id":"n-29","typ":"natur","frage":"Wovon hängt ab, ob jemand trockenes oder feuchtes Ohrenschmalz hat?","antwort":"Von einem einzigen Gen, ABCC11.","erklaerung":"Eine einzelne Basenänderung entscheidet zwischen krümelig-trocken und klebrig-feucht. In Ostasien ist die trockene Variante sehr häufig, in Europa und Afrika die feuchte. Das Gen beeinflusst auch den Achselgeruch."},
  {"id":"n-30","typ":"natur","frage":"Woher kommt der typische Geruch, wenn Regen auf trockene Erde fällt?","antwort":"Von Geosmin – einem Stoff, den Bodenbakterien produzieren, freigesetzt von den aufprallenden Tropfen.","erklaerung":"Den Geruch nennt man Petrichor. Menschen riechen Geosmin schon in winzigsten Konzentrationen. Regentropfen schleudern beim Aufprall feine Aerosole hoch, die den Duft in die Luft tragen."},
  {"id":"n-31","typ":"natur","frage":"Was kann entstehen, wenn ein Blitz in Sand einschlägt?","antwort":"Hohle Glasröhren, sogenannte Fulgurite.","erklaerung":"Der Blitz erhitzt den Sand entlang seines Weges in den Boden auf über 1.800 °C, das Quarz schmilzt und erstarrt sofort zu Glas. Manche Fulgurite sind verzweigt wie Wurzeln und mehrere Meter lang."},
  {"id":"n-32","typ":"natur","frage":"Was ist die „Morning Glory“ über dem Golf von Carpentaria in Australien?","antwort":"Eine riesige röhrenförmige Wolkenwalze, die bis zu 1000 km lang sein kann und morgens übers Land rollt.","erklaerung":"Sie tritt vor allem im September und Oktober bei Burketown auf. Segelflieger reiten auf der Aufwindseite der Wolke wie Surfer auf einer Welle."},
  {"id":"n-33","typ":"natur","frage":"Welche Form haben größere Regentropfen, während sie fallen?","antwort":"Wie ein Hamburgerbrötchen, unten platt","erklaerung":"Kleine Tropfen sind kugelrund. Bei größeren drückt der Luftwiderstand die Unterseite flach. Die klassische Tränenform kommt in Wirklichkeit nicht vor; über etwa 5 mm zerplatzen Tropfen."},
  {"id":"n-34","typ":"natur","frage":"Was passiert, wenn an bestimmten Wüstendünen eine Sandlawine abrutscht?","antwort":"Die Düne fängt an zu brummen, manchmal so laut wie ein tief fliegendes Flugzeug.","erklaerung":"Solche „singenden Dünen“ gibt es etwa in der Sahara, in China und Kalifornien. Der tiefe Ton kann über 100 Dezibel erreichen und minutenlang anhalten. Dafür braucht es sehr trockenen, gleichförmigen Sand."},
  {"id":"n-35","typ":"natur","frage":"Wie bewegen sich die „wandernden Steine“ im Death Valley?","antwort":"Dünne Eisplatten auf dem überfluteten Boden schieben sie bei leichtem Wind langsam weiter.","erklaerung":"Jahrzehntelang war unklar, wer die teils hunderte Kilo schweren Steine bewegt. 2014 beobachteten Forscher es erstmals mit GPS und Zeitraffer: Nach frostigen Nächten zerbricht morgens das Eis und treibt die Steine an."},
  {"id":"n-36","typ":"natur","frage":"Woraus besteht das Gestein am Gipfel des Mount Everest?","antwort":"Aus Meeresboden. Kalkstein mit Fossilien von Trilobiten und anderen Meerestieren.","erklaerung":"Das Gestein entstand vor rund 450 Millionen Jahren in einem Ozean. Die Kollision der indischen mit der eurasischen Platte hat es fast neun Kilometer in die Höhe gehoben."},
  {"id":"n-37","typ":"natur","frage":"Wonach riechen Raumanzüge laut Astronauten nach einem Weltraumausstieg?","antwort":"Nach angebratenem Steak, heißem Metall und Schweißdämpfen.","erklaerung":"Im Vakuum riecht man nichts, aber an den Anzügen haftende Moleküle verströmen den Geruch, sobald die Luftschleuse wieder gefüllt ist. Als Ursache gelten unter anderem reaktiver atomarer Sauerstoff und Verbrennungsrückstände."},
  {"id":"n-38","typ":"natur","frage":"Welche Farbe hat ein Sonnenuntergang auf dem Mars?","antwort":"Blau.","erklaerung":"Der feine Marsstaub streut blaues Licht bevorzugt nach vorne, also in Richtung Sonne. Rund um die untergehende Sonne entsteht dadurch ein bläulicher Schein, während der Tageshimmel eher rötlich-beige ist. Rover haben das fotografiert."},
  {"id":"n-39","typ":"natur","frage":"Was passiert mit der Körpergröße von Astronauten im All?","antwort":"Sie werden bis zu drei Prozent größer, weil sich die Wirbelsäule ohne Schwerkraft streckt.","erklaerung":"Die Bandscheiben dehnen sich aus, wenn kein Gewicht auf ihnen lastet. Das macht einige Zentimeter aus, verursacht oft Rückenschmerzen und bildet sich nach der Rückkehr zur Erde wieder zurück."},
  {"id":"n-40","typ":"natur","frage":"Warum lassen Katzen Süßigkeiten meistens links liegen?","antwort":"Sie können süß gar nicht schmecken – das Gen für den Süßrezeptor ist bei ihnen kaputt.","erklaerung":"Bei Katzen ist das Gen Tas1r2 durch eine Mutation funktionslos geworden. Als reine Fleischfresser brauchten sie den Süßgeschmack nicht. Dasselbe gilt für Löwen, Tiger und andere Katzenarten."},
  {"id":"n-41","typ":"natur","frage":"Wie schlafen Stockenten am Rand einer Gruppe, um nicht überrascht zu werden?","antwort":"Mit einer Gehirnhälfte. Das nach außen gerichtete Auge bleibt offen.","erklaerung":"Beim unihemisphärischen Schlaf ruht nur eine Hirnhälfte, die andere wacht und steuert das offene Auge. Enten in der Mitte der Gruppe schlafen dagegen häufiger mit beiden Augen zu."},
  {"id":"n-42","typ":"natur","frage":"Wie töten Japanische Honigbienen eine Riesenhornisse, die in ihren Stock eindringt?","antwort":"Hunderte Bienen umhüllen sie zu einem Ball und heizen ihn mit ihren Flugmuskeln auf etwa 46 °C auf.","erklaerung":"Die Hornisse stirbt an der Hitze und dem angestauten Kohlendioxid, die Bienen vertragen ein paar Grad mehr. Europäische Honigbienen beherrschen diese Taktik nicht und sind den Hornissen fast schutzlos ausgeliefert."},
  {"id":"n-43","typ":"natur","frage":"Wozu schneiden Blattschneiderameisen Blattstücke ab und schleppen sie ins Nest?","antwort":"Sie fressen die Blätter nicht, sondern düngen damit einen Pilz, den sie anbauen und ernten.","erklaerung":"Die Ameisen betreiben seit Millionen von Jahren Landwirtschaft. Ihr Pilzgarten ernährt die ganze Kolonie, und eine neue Königin nimmt beim Hochzeitsflug ein Stück Pilz im Mund mit."},
  {"id":"n-44","typ":"natur","frage":"Was passiert, wenn das Weibchen einer Gruppe von Anemonenfischen stirbt?","antwort":"Das größte Männchen wechselt das Geschlecht und wird zum neuen Weibchen.","erklaerung":"Anemonenfische schlüpfen alle als Männchen. Nur das dominanteste Tier wird weiblich, das zweitgrößte ist das Brutmännchen. Im Film „Findet Nemo“ hätte Nemos Vater also eigentlich zur Mutter werden müssen."},
  {"id":"n-45","typ":"natur","frage":"Wie alt kann ein Grönlandhai werden?","antwort":"Mehrere Jahrhunderte – das älteste untersuchte Tier wurde auf rund 400 Jahre geschätzt.","erklaerung":"Das Alter wurde 2016 per Radiokarbonmethode an den Augenlinsen bestimmt. Grönlandhaie wachsen nur etwa einen Zentimeter pro Jahr und werden vermutlich erst mit über 100 Jahren geschlechtsreif."},
  {"id":"n-46","typ":"natur","frage":"Womit schmecken Schmetterlinge, ob ein Blatt für ihre Eier geeignet ist?","antwort":"Mit den Füßen","erklaerung":"An den Beinen sitzen Geschmackssinneszellen. Weibchen trommeln vor der Eiablage auf Blättern herum, um die richtige Futterpflanze für ihre Raupen zu erkennen."},
  {"id":"n-47","typ":"natur","frage":"Was ist der rötliche Schweiß, den Flusspferde absondern?","antwort":"Weder Blut noch Schweiß, sondern ein Sekret mit roten und orangen Farbstoffen, das als Sonnencreme und Antibiotikum wirkt.","erklaerung":"Japanische Forscher identifizierten 2004 die Farbstoffe Hipposudorsäure und Norhipposudorsäure. Sie absorbieren UV-Licht und hemmen Bakterien – praktisch bei der dünnen, empfindlichen Haut der Tiere."},
  {"id":"n-48","typ":"natur","frage":"Wie jagen Buckelwale gemeinsam Fischschwärme?","antwort":"Sie schwimmen in Spiralen unter dem Schwarm und blasen dabei Luft aus. Die aufsteigenden Blasen bilden ein Netz, das die Fische einschließt.","erklaerung":"Dann schießen die Wale mit offenem Maul von unten durch das Blasennetz nach oben. Die Gruppen arbeiten dabei mit verteilten Rollen, manche Tiere treiben die Fische zusätzlich mit Rufen zusammen."},
  {"id":"n-49","typ":"natur","frage":"Was teilen Gemeine Vampirfledermäuse mit Artgenossen, die in der Nacht leer ausgegangen sind?","antwort":"Blut – sie würgen einen Teil ihrer Mahlzeit wieder hoch.","erklaerung":"Ohne Blutmahlzeit verhungert eine Vampirfledermaus nach etwa zwei bis drei Nächten. Studien zeigen: Tiere, die früher geteilt haben, bekommen später selbst eher etwas ab."},
  {"id":"n-50","typ":"natur","frage":"Wie lange leben periodische Zikaden in Nordamerika unter der Erde, bevor sie herauskommen?","antwort":"Je nach Art genau 13 oder 17 Jahre.","erklaerung":"Die Larven saugen an Baumwurzeln. Dann schlüpfen in einer Region Milliarden Tiere fast gleichzeitig, so viele, dass Fressfeinde nur einen Bruchteil erwischen. Der Lärm der Männchen kann über 90 Dezibel erreichen."},
  {"id":"n-51","typ":"natur","frage":"Wie machen sich Glasfrösche im Schlaf fast unsichtbar?","antwort":"Sie verstecken fast alle roten Blutkörperchen in ihrer Leber.","erklaerung":"Beim Schlafen ziehen die Frösche rund 90 Prozent ihrer roten Blutzellen aus dem Kreislauf ab, wodurch der Körper bis zu dreimal durchsichtiger wird. Warum die Blutzellen dabei nicht verklumpen, interessiert auch die Medizin."},
  {"id":"n-52","typ":"natur","frage":"Woher bekommt die Hornhaut des menschlichen Auges ihren Sauerstoff?","antwort":"Direkt aus der Luft – über den Tränenfilm, denn sie hat keine Blutgefäße.","erklaerung":"Blutgefäße würden die Sicht trüben, deshalb ist die Hornhaut gefäßfrei. Bei geschlossenen Augen kommt Sauerstoff aus den Gefäßen der Lidinnenseite – darum sollen viele Kontaktlinsen nicht über Nacht getragen werden."},
  {"id":"n-53","typ":"natur","frage":"Warum riechen Schweißfüße oft nach Käse?","antwort":"Weil Brevibacterien drauf wohnen – enge Verwandte der Bakterien, die Limburger reifen lassen.","erklaerung":"Schweiß selbst ist fast geruchlos. Erst Bakterien zersetzen Eiweiße und Hautreste zu Schwefelverbindungen wie Methanthiol. Brevibacterium linens wird gezielt zur Reifung von Rotschmierkäse eingesetzt."},
  {"id":"n-54","typ":"natur","frage":"Welche Körperöffnung bildet sich beim menschlichen Embryo als erste?","antwort":"Der After","erklaerung":"Menschen gehören zu den Neumündern (Deuterostomia): Die Urmundöffnung des frühen Embryos wird zum After, der Mund entsteht erst später neu. Bei Insekten und Schnecken ist es umgekehrt."},
  {"id":"n-55","typ":"natur","frage":"Woher stammt ein großer Teil des weißen Sandes an Hawaiis Stränden?","antwort":"Aus dem Kot von Papageifischen.","erklaerung":"Papageifische raspeln Algen von Korallen ab und zermahlen dabei den Kalk. Was sie ausscheiden, ist feiner weißer Sand – ein großer Fisch produziert davon mehrere hundert Kilo pro Jahr."},
  {"id":"n-56","typ":"natur","frage":"Warum leuchtet der indonesische Vulkan Kawah Ijen nachts blau?","antwort":"Aus Spalten strömen Schwefelgase, die sich an der Luft entzünden und mit blauer Flamme brennen.","erklaerung":"Die Gase treten mit bis zu 600 °C aus. Ein Teil kondensiert zu flüssigem Schwefel, der brennend die Hänge hinunterläuft. Tagsüber sieht man die Flammen kaum, nachts entsteht das Bild blauer Lava."},
  {"id":"n-57","typ":"natur","frage":"Was steckt dahinter, wenn es in Mitteleuropa „Blutregen“ gibt?","antwort":"Saharastaub. Der Wind trägt ihn hoch und weit nach Norden, der Regen wäscht ihn aus.","erklaerung":"Der rötliche Staub färbt Regentropfen, Autos und Schnee orange bis rötlich. Früher galt Blutregen als böses Omen. Mitunter reicht der Staub sogar bis nach Skandinavien."},
  {"id":"n-58","typ":"natur","frage":"Welche Farbe hat ein Nebelbogen?","antwort":"Fast weiß, höchstens mit einem Hauch Rot außen und Blau innen.","erklaerung":"Nebelbögen entstehen wie Regenbögen, aber in sehr kleinen Wassertröpfchen. Durch Beugung verschmieren die Farben so stark, dass sie sich zu Weiß mischen. Man sieht sie oft im Gebirge oder auf See."},
  {"id":"n-59","typ":"natur","frage":"Wodurch entsteht Haareis, das an feuchten Winternächten auf totem Holz wächst?","antwort":"Durch den Pilz Exidiopsis effusa.","erklaerung":"Ohne den Pilz im Holz bildet sich kein Haareis. Er verhindert, dass die feinen, bis zu 0,02 mm dünnen Eisfäden zu größeren Kristallen zusammenwachsen. Alfred Wegener vermutete das schon 1918, bewiesen wurde es 2015."},
  {"id":"n-60","typ":"natur","frage":"In welche Richtung zeigt der Schweif eines Kometen?","antwort":"Immer von der Sonne weg – auch wenn der Komet sich gerade von ihr entfernt und der Schweif dann vorausfliegt.","erklaerung":"Der Ionenschweif wird vom Sonnenwind weggeblasen, der Staubschweif vom Strahlungsdruck des Lichts. Darum hängt die Richtung nicht von der Flugbahn ab. Viele Kometen haben beide Schweife getrennt sichtbar."}
];

